function normalizeDepartmentCode(dept) {
    if (!dept) return '';
    const clean = String(dept).trim();
    const upper = clean.toUpperCase();
    const mapping = {
        'PRD': 'PRD',
        'PRD (PRODUCTION)': 'PRD',
        'PRODUCTION': 'PRD',
        'ENG': 'ENG',
        'ENG (ENGINEERING)': 'ENG',
        'ENGINEERING': 'ENG',
        'EUT': 'EUT',
        'EUT (ENGINEER UTILITY)': 'EUT',
        'EUT (ENGINEERING UTILITY)': 'EUT',
        'ENGINEER UTILITY': 'EUT',
        'ENGINEERING UTILITY': 'EUT',
        'UTILITY': 'EUT',
        'UTL': 'EUT',
        'EPR': 'EPR',
        'EPR (ENGINEERING PRODUKSI)': 'EPR',
        'EPR (ENGINEERING PRODUCTION)': 'EPR',
        'ENGINEERING PRODUKSI': 'EPR',
        'ENGINEERING PRODUCTION': 'EPR',
        'GA': 'GA',
        'GA (GENERAL AFFAIR)': 'GA',
        'GENERAL AFFAIR': 'GA',
        'GENERAL AFFAIRS': 'GA',
        'QC': 'QC',
        'QC (QUALITY CONTROL)': 'QC',
        'QUALITY CONTROL': 'QC',
        'WRH': 'WRH',
        'WRH (WAREHOUSE)': 'WRH',
        'WAREHOUSE': 'WRH',
        'MAINTENANCE': 'WRH',
        'EKSPEDISI': 'WRH',
        'TMB': 'TMB',
        'TMB (TIMBANGAN)': 'TMB',
        'TIMBANGAN': 'TMB',
        'HSE': 'HSE'
    };
    if (mapping[upper]) return mapping[upper];

    // Substring / Role prefix detection (check EPR before PRD)
    if (upper.includes('EUT') || upper.includes('UTILITY') || upper.includes('UTL')) return 'EUT';
    if (upper.includes('EPR')) return 'EPR';
    if (upper.includes('PRD') || upper.includes('PRODUCTION')) return 'PRD';
    if (upper.includes('ENG') || upper.includes('ENGINEERING')) return 'ENG';
    if (upper.includes('GA') || upper.includes('GENERAL AFFAIR')) return 'GA';
    if (upper.includes('QC') || upper.includes('QUALITY CONTROL')) return 'QC';
    if (upper.includes('WRH') || upper.includes('WAREHOUSE') || upper.includes('MAINTENANCE')) return 'WRH';
    if (upper.includes('TMB') || upper.includes('TIMBANGAN')) return 'TMB';
    if (upper.includes('HSE')) return 'HSE';

    return clean;
}

function getUserDepartmentCode() {
    if (!state.currentUser) return '';
    let deptCode = normalizeDepartmentCode(state.currentUser.dept);
    const validDepts = ['PRD', 'ENG', 'EPR', 'GA', 'QC', 'WRH', 'TMB', 'EUT', 'HSE'];
    if (!deptCode || !validDepts.includes(deptCode)) {
        const fromRole = normalizeDepartmentCode(state.currentUser.role);
        if (fromRole && validDepts.includes(fromRole)) {
            deptCode = fromRole;
        } else {
            const fromUsername = normalizeDepartmentCode(state.currentUser.username);
            if (fromUsername && validDepts.includes(fromUsername)) {
                deptCode = fromUsername;
            }
        }
    }
    return validDepts.includes(deptCode) ? deptCode : (deptCode || '');
}

// ponytail: Robust helper to resolve document URL from string, object, or relative path
function getDocUrl(doc) {
    if (!doc) return '';
    if (typeof doc === 'string') return doc.trim();
    if (typeof doc === 'object') {
        return (doc.path || doc.url || doc.file || doc.src || doc.filePath || '').toString().trim();
    }
    return String(doc).trim();
}
window.getDocUrl = getDocUrl;

// ponytail: Robust helper to resolve document display name or filename
function getDocFilename(doc, fallback) {
    if (!doc) return fallback || '';
    if (typeof doc === 'object' && doc.name && typeof doc.name === 'string') return doc.name.trim();
    const url = getDocUrl(doc);
    if (!url) return fallback || '';
    const cleanUrl = url.split('?')[0];
    const filename = cleanUrl.split('/').pop();
    return filename || fallback || url;
}
window.getDocFilename = getDocFilename;

// ponytail: helper to determine drawing phase (1=Schedule, 2=On Progress, 3=Done, 4=Archive)
function getDrawingPhase(d) {
    if (!d) return 1;
    const isArchived = d.is_archived === 1 || d.is_archived === '1' || d.status === 'Archived' || d.status === 'Rejected' || (typeof isDrawingAutoArchiveDue === 'function' && isDrawingAutoArchiveDue(d));
    if (isArchived) return 4;
    const status = d.status || 'Pending Foreman Approval';
    const hasFile = !!d.file_path;
    if (status === 'Archived' || status === 'Cancelled' || status === 'Rejected') {
        return 4;
    } else if (status === 'Completed' || status === 'Pending Requester Approval' || status === 'Pending Supervisor Approval' || status === 'Pending Manager Approval' || status === 'Pending Factory Manager Approval') {
        return 3;
    } else if (status === 'Pending Foreman Approval' || status === 'Pending Dept Approval') {
        return hasFile ? 3 : 1;
    } else if (status === 'On Progress' || status === 'In Progress') {
        return 2;
    } else if (status === 'Checking' || status === 'Requested' || status === 'Schedule') {
        return 1;
    }
    return 1;
}
window.getDrawingPhase = getDrawingPhase;

// ponytail: helper to extract exact timestamp when Technical Drawing was completed
function getDrawingCompletionDate(d) {
    if (!d) return null;
    if (d.completed_at) {
        const dt = new Date(d.completed_at);
        if (!isNaN(dt.getTime())) return dt;
    }
    const logs = parseLogs(d.logs || d);
    if (Array.isArray(logs) && logs.length > 0) {
        for (let i = logs.length - 1; i >= 0; i--) {
            const msg = (logs[i].cleanMessage || logs[i].message || '').toLowerCase();
            const dtStr = logs[i].date || '';
            if (msg.includes('completed') || msg.includes('selesai') || msg.includes('disetujui') || msg.includes('approval') || msg.includes('diarsip')) {
                if (dtStr) {
                    const parsed = new Date(dtStr.replace(' ', 'T'));
                    if (!isNaN(parsed.getTime())) return parsed;
                    const parsedPlain = new Date(dtStr);
                    if (!isNaN(parsedPlain.getTime())) return parsedPlain;
                }
            }
        }
        if (d.status === 'Completed' || d.status === 'Archived' || d.status === 'Done') {
            const lastLog = logs[logs.length - 1];
            if (lastLog && lastLog.date) {
                const parsed = new Date(lastLog.date.replace(' ', 'T'));
                if (!isNaN(parsed.getTime())) return parsed;
                const parsedPlain = new Date(lastLog.date);
                if (!isNaN(parsedPlain.getTime())) return parsedPlain;
            }
        }
    }
    const fallbackStr = d.uploaded_at || d.targetDate || d.created_at || '';
    if (fallbackStr) {
        const dt = new Date(fallbackStr);
        if (!isNaN(dt.getTime())) return dt;
    }
    return null;
}
window.getDrawingCompletionDate = getDrawingCompletionDate;

// ponytail: helper to extract exact timestamp when General EJO was completed
function getGeneralEjoCompletionDate(ejo) {
    if (!ejo) return null;
    if (ejo.qty_work_done_date) {
        const d = new Date(ejo.qty_work_done_date);
        if (!isNaN(d.getTime())) return d;
    }
    if (ejo.completed_at) {
        const d = new Date(ejo.completed_at);
        if (!isNaN(d.getTime())) return d;
    }
    const logs = parseLogs(ejo);
    if (Array.isArray(logs) && logs.length > 0) {
        for (let i = logs.length - 1; i >= 0; i--) {
            const msg = (logs[i].cleanMessage || logs[i].message || '').toLowerCase();
            const dtStr = logs[i].date || '';
            if (msg.includes('completed') || msg.includes('selesai') || msg.includes('pending user approval') || msg.includes('pending requester approval') || msg.includes('waiting for user approval')) {
                if (dtStr) {
                    const parsed = new Date(dtStr.replace(' ', 'T'));
                    if (!isNaN(parsed.getTime())) return parsed;
                    const parsedPlain = new Date(dtStr);
                    if (!isNaN(parsedPlain.getTime())) return parsedPlain;
                }
            }
        }
        if (ejo.status === 'Completed' || ejo.status === 'Pending User Approval' || ejo.status === 'Pending Requester Approval') {
            const lastLog = logs[logs.length - 1];
            if (lastLog && lastLog.date) {
                const parsed = new Date(lastLog.date.replace(' ', 'T'));
                if (!isNaN(parsed.getTime())) return parsed;
                const parsedPlain = new Date(lastLog.date);
                if (!isNaN(parsedPlain.getTime())) return parsedPlain;
            }
        }
    }
    const fallbackStr = ejo.updated_at || ejo.createdDate || ejo.created_at || ejo.targetDate;
    if (fallbackStr) {
        const d = new Date(fallbackStr);
        if (!isNaN(d.getTime())) return d;
    }
    return null;
}

// ponytail: helper to reliably detect whether an item is a Drawing EJO across all contexts
function isDrawingItem(item) {
    if (!item) return false;
    if (item.isDrawing === true) return true;
    if (item.drawing_type || item.drafter || item.etiket_category || item.etiket_orientation || item.uploaded_at) return true;
    const id = String(item.id || item.ejo_id || '');
    if (id.startsWith('DRW') || id.startsWith('DEJO') || id.startsWith('DWG')) return true;
    if (typeof state !== 'undefined' && Array.isArray(state.drawings) && state.drawings.some(d => d && d.id === item.id)) return true;
    const cat = String(item.category || '').toLowerCase();
    if (cat === 'drawing') return true;
    return false;
}
window.isDrawingItem = isDrawingItem;

// ponytail: helper to check if an EJO / item is cancelled
function isItemCancelled(e) {
    if (!e) return false;
    const st = (e.status || '').toLowerCase();
    return st === 'cancelled' || st === 'rejected' || st.includes('batal') || st.includes('cancel') || e.is_cancelled === 1 || e.is_cancelled === '1';
}

// ponytail: helper to check if an EJO / Drawing / Project is completed / done (including Pending User/Dept Approval)
function isItemDone(e) {
    if (!e) return false;
    if (isItemCancelled(e)) return false;
    const st = (e.status || '').toLowerCase();

    // Direct status matches
    if (st === 'completed' || st === 'done') return true;

    // Check phase for Drawing EJO FIRST (priority before general EJO to avoid prefix collision)
    if (isDrawingItem(e) && typeof getDrawingPhase === 'function') {
        const ph = getDrawingPhase(e);
        return ph === 3 || ph === 4; // Phase 3 = Done, Phase 4 = Archive (non-cancelled)
    }

    // Check phase for General EJO
    if (typeof getGeneralEjoPhase === 'function') {
        const ph = getGeneralEjoPhase(e);
        return ph === 3 || ph === 4; // Phase 3 = Done, Phase 4 = Archive (non-cancelled)
    }

    if (st === 'pending user approval' || st === 'pending requester approval' || st === 'pending approval') {
        return true;
    }
    if (st === 'waiting dept approval' && e.has_signed) {
        return true;
    }

    // Check phase for Project
    if (e.phase === 4 || e.phase === 5 || e.phase === '4' || e.phase === '5') {
        return true;
    }
    if (e.is_archived === 1 || e.is_archived === '1' || st === 'archived') {
        return true;
    }

    return false;
}

// ponytail: helper to check if an item (General EJO or Drawing) is in Outstanding (Schedule or On Progress)
function isItemOutstanding(e) {
    if (!e) return false;
    if (isItemDone(e) || isItemCancelled(e)) return false;
    if (e.is_archived === 1 || e.is_archived === '1' || (e.status || '').toLowerCase() === 'archived') return false;

    if (isDrawingItem(e) && typeof getDrawingPhase === 'function') {
        const ph = getDrawingPhase(e);
        return ph === 1 || ph === 2;
    }

    if (typeof getGeneralEjoPhase === 'function') {
        const ph = getGeneralEjoPhase(e);
        return ph === 1 || ph === 2;
    }

    const st = (e.status || '').toLowerCase();
    if (st.includes('progress') || st.includes('checking') || st === 'requested' || st === 'approved' || st === 'waiting dept approval' || st === 'pending revision') {
        return true;
    }
    return false;
}
window.isItemOutstanding = isItemOutstanding;

// ponytail: robust date parser helper converting any input date format to YYYY-MM-DD
function parseDateToYYYYMMDD(input) {
    if (!input) return '';
    if (input instanceof Date) {
        if (isNaN(input.getTime())) return '';
        const y = input.getFullYear();
        const m = String(input.getMonth() + 1).padStart(2, '0');
        const d = String(input.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    }
    const str = String(input).trim();
    if (!str) return '';

    // Standard ISO pattern: YYYY-MM-DD
    const isoMatch = str.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
    if (isoMatch) {
        const y = isoMatch[1];
        const m = String(parseInt(isoMatch[2], 10)).padStart(2, '0');
        const d = String(parseInt(isoMatch[3], 10)).padStart(2, '0');
        return `${y}-${m}-${d}`;
    }

    // DD-MM-YYYY or DD/MM/YYYY pattern
    const ddmmyyyyMatch = str.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
    if (ddmmyyyyMatch) {
        const d = String(parseInt(ddmmyyyyMatch[1], 10)).padStart(2, '0');
        const m = String(parseInt(ddmmyyyyMatch[2], 10)).padStart(2, '0');
        const y = ddmmyyyyMatch[3];
        return `${y}-${m}-${d}`;
    }

    // Textual month pattern: e.g. "12 Aug 2026", "12 Agu 2026, 14:30 WIB", "12 Agustus 2026"
    const textMonthMatch = str.match(/(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})/);
    if (textMonthMatch) {
        const day = String(parseInt(textMonthMatch[1], 10)).padStart(2, '0');
        const monthName = textMonthMatch[2].toLowerCase();
        const year = textMonthMatch[3];

        const monthMap = {
            jan: '01', januari: '01', january: '01',
            feb: '02', februari: '02', february: '02',
            mar: '03', maret: '03', march: '03',
            apr: '04', april: '04',
            mei: '05', may: '05',
            jun: '06', juni: '06', june: '06',
            jul: '07', juli: '07', july: '07',
            agu: '08', aug: '08', agustus: '08', august: '08',
            sep: '09', september: '09',
            okt: '10', oct: '10', oktober: '10', october: '10',
            nov: '11', november: '11',
            des: '12', dec: '12', desember: '12', december: '12'
        };
        const month = monthMap[monthName] || '01';
        return `${year}-${month}-${day}`;
    }

    // Fallback: new Date(str)
    const dt = new Date(str);
    if (!isNaN(dt.getTime())) {
        const y = dt.getFullYear();
        const m = String(dt.getMonth() + 1).padStart(2, '0');
        const d = String(dt.getDate()).padStart(2, '0');
        return `${y}-${m}-${d}`;
    }
    return '';
}

// ponytail: helper to extract completed date string (YYYY-MM-DD) for any EJO item
function getItemCompletionDateString(e) {
    if (!e) return '';
    const isClosed = isItemDone(e) || isItemCancelled(e);
    if (!isClosed) return '';
    let raw = e.qty_work_done_date || e.completed_at;
    if (!raw) {
        const logs = parseLogs(e.logs || e);
        if (Array.isArray(logs) && logs.length > 0) {
            const compLog = logs.find(l => {
                if (!l) return false;
                const msg = (l.cleanMessage || l.message || '').toLowerCase();
                if (msg.includes('dibuat') || msg.includes('import excel') || msg.includes('created')) return false;
                return msg.includes('selesai') ||
                    msg.includes('completed') ||
                    msg.includes('pending user approval') ||
                    msg.includes('pending requester approval') ||
                    msg.includes('waiting for user approval') ||
                    msg.includes('batal') ||
                    msg.includes('cancelled') ||
                    msg.includes('reject') ||
                    msg.includes('close');
            });
            if (compLog && compLog.date) {
                raw = compLog.date;
            }
        }
    }
    if (!raw) raw = e.targetDate || e.createdDate || e.updated_at || e.created_at || '';
    return parseDateToYYYYMMDD(raw);
}

// ponytail: check if Technical Drawing has been completed for >= 3 days without user confirmation
function isDrawingAutoArchiveDue(drawing, maxDays = 3) {
    if (!drawing || (drawing.is_archived === 1 || drawing.is_archived === '1' || drawing.status === 'Archived')) return false;
    if (drawing.status !== 'Completed' && drawing.status !== 'Cancelled') return false;
    const compDate = getDrawingCompletionDate(drawing);
    if (!compDate) return false;
    const now = new Date();
    const diffMs = now.getTime() - compDate.getTime();
    const threeDaysMs = maxDays * 24 * 60 * 60 * 1000;
    return diffMs >= threeDaysMs;
}
window.isDrawingAutoArchiveDue = isDrawingAutoArchiveDue;

// ponytail: check if General EJO has been completed for >= 3 days without user confirmation
// Special rule for Repair Part: MUST have repair cost data filled (repair_cost_per_day > 0 and repair_duration > 0)
// and quantity requirements fulfilled before auto-archiving.
function isGeneralEjoAutoArchiveDue(ejo, maxDays = 3) {
    if (!ejo || (ejo.is_archived === 1 || ejo.is_archived === '1')) return false;
    if (ejo.status !== 'Completed' && ejo.status !== 'Cancelled') return false;

    // ponytail: Repair Part category validation check before auto-archiving
    const isRepairPartCategory = ejo.category === 'Repair Part' || (ejo.category && ejo.category.toLowerCase().includes('repair'));
    if (isRepairPartCategory && ejo.status !== 'Cancelled' && !(ejo.status || '').includes('Ditolak')) {
        const hasRepairCost = (parseFloat(ejo.repair_cost_per_day) > 0 && parseInt(ejo.repair_duration) > 0);
        if (!hasRepairCost) return false;

        const qVal = parseInt(ejo.quantity || 1);
        const qNeededTarget = (ejo.qty_needed_target !== undefined && ejo.qty_needed_target !== null && parseInt(ejo.qty_needed_target) > 0)
            ? parseInt(ejo.qty_needed_target)
            : ((ejo.qty_needed !== undefined && ejo.qty_needed !== null && parseInt(ejo.qty_needed) > 0) ? parseInt(ejo.qty_needed) : 1);
        const qStockTarget = (ejo.qty_stock_target !== undefined && ejo.qty_stock_target !== null && parseInt(ejo.qty_stock_target) > 0)
            ? parseInt(ejo.qty_stock_target)
            : Math.max(0, qVal - qNeededTarget);

        const qNeededActual = (ejo.qty_needed_actual !== undefined && ejo.qty_needed_actual !== null)
            ? parseInt(ejo.qty_needed_actual)
            : 0;
        const qStockActual = (ejo.qty_stock !== undefined && ejo.qty_stock !== null) ? parseInt(ejo.qty_stock) : 0;

        if ((qNeededTarget > 0 && qNeededActual < qNeededTarget) || (qStockTarget > 0 && qStockActual < qStockTarget)) {
            return false;
        }
    }

    const compDate = getGeneralEjoCompletionDate(ejo);
    if (!compDate) return false;
    const now = new Date();
    const diffMs = now.getTime() - compDate.getTime();
    const threeDaysMs = maxDays * 24 * 60 * 60 * 1000;
    return diffMs >= threeDaysMs;
}

// ponytail: helper to determine General EJO phase (1=Schedule, 2=On Progress, 3=Done, 4=Archive)
function getGeneralEjoPhase(e) {
    if (!e) return 1;
    const isArchived = e.is_archived === 1 || e.is_archived === '1' || e.status === 'Archived' || e.status === 'Rejected' || isGeneralEjoAutoArchiveDue(e);
    if (isArchived) return 4;
    const status = e.status || '';
    if (status === 'Completed' || status === 'Cancelled' || status === 'Done' ||
        status === 'Pending User Approval' || status === 'Pending Requester Approval' ||
        status === 'Pending Approval' || status === 'Pending Foreman Approval' ||
        status === 'Pending Supervisor Approval' || status === 'Pending Manager Approval' ||
        status === 'Pending Factory Manager Approval') {
        return 3;
    }
    if ((status.startsWith('In Progress') && !status.includes('(Revisi')) || status === 'On Progress') {
        return 2;
    }
    return 1;
}

function applyUserDepartmentToFormSelect(selectId) {
    const selectEl = document.getElementById(selectId);
    if (!selectEl || !state.currentUser) return;

    const userDeptCode = getUserDepartmentCode();
    if (userDeptCode) {
        selectEl.value = userDeptCode;
    }

    const isGlobalLead = isGlobalLeadUser();
    selectEl.disabled = !isGlobalLead && !!userDeptCode;

    const fieldContainer = selectEl.closest('.form-field');
    if (fieldContainer) {
        if (!isGlobalLead && !!userDeptCode) {
            fieldContainer.style.display = 'none';
        } else {
            fieldContainer.style.display = '';
        }
    }
}

function getDepartmentDisplayLabel(dept) {
    const code = normalizeDepartmentCode(dept);
    const option = DEPARTMENT_OPTIONS.find(item => item.value === code);
    return option ? option.label : (code || dept || '-');
}

function departmentMatchesFilter(dept, filterVal) {
    return filterVal === 'all' || normalizeDepartmentCode(dept) === filterVal;
}

function getRoleLevel(role) {
    if (!role) return 0;
    if (ROLE_LEVELS[role] !== undefined) return ROLE_LEVELS[role];
    if (role.startsWith('Manager ')) return 80;
    if (role.startsWith('Supervisor ')) return 60;
    if (role.startsWith('user_') || role.startsWith('Staff ') || role.startsWith('User ')) return 10;
    return 0;
}

function isLeadRole(role) {
    return getRoleLevel(role) >= 40;
}

function isForemanAdminRole(role) {
    return role === 'Foreman Eng' || role === 'Foreman' || role === 'Admin Eng' || role === 'Server';
}

function isDrafterRole(role) {
    return DRAFTER_ROLES.includes(role);
}

function canUserImportDrawing(userOrRole) {
    if (!userOrRole) return false;
    const role = typeof userOrRole === 'string' ? userOrRole : (userOrRole.role || '');
    return isDrafterRole(role) || isForemanAdminRole(role);
}



// ponytail: helper to check if an engineer name string matches user's fullname or username case-insensitively
function checkIsAssigned(engineerField, currentUser) {
    if (!currentUser || !engineerField) return false;
    const userFull = (currentUser.fullname || '').toLowerCase().trim();
    const userName = (currentUser.username || '').toLowerCase().trim();
    const list = engineerField.split(',').map(name => name.toLowerCase().trim());
    return (userFull !== '' && list.includes(userFull)) || (userName !== '' && list.includes(userName));
}

// ponytail: helper to check if role is a standard user or a department-specific staff
function isOrdinaryUser(role) {
    return role === 'User' || (role || '').startsWith('Staff ') || (role || '').startsWith('User ') || (role || '').startsWith('user_');
}

// ponytail: helper to check if a user is authorized as department supervisor/manager for a specific EJO department (supports user dept, role name e.g. Supervisor EPR, and drawing requester's department)
function isDepartmentApprover(user, ejoDept, drawingObj) {
    if (!user) return false;
    const role = user.role || '';
    const isServer = role === 'Server' || user.username === 'server' || role === 'Admin Eng';
    if (isServer) return true;

    const roleLower = role.toLowerCase();
    const isApproverRole = roleLower.includes('supervisor') || roleLower.includes('spv') || roleLower.includes('manager') || roleLower.includes('plant manager');
    if (!isApproverRole) return false;

    // Extract user department code
    let userDeptCode = normalizeDepartmentCode(user.dept);
    if (!userDeptCode && role) {
        const parts = role.toUpperCase().split(/[\s_]+/);
        const codePart = parts.find(p => p !== 'SUPERVISOR' && p !== 'SPV' && p !== 'MANAGER' && p !== 'PLANT' && p.length >= 2);
        if (codePart) userDeptCode = normalizeDepartmentCode(codePart);
    }

    // Extract target drawing department code
    let targetDeptCode = normalizeDepartmentCode(typeof ejoDept === 'string' ? ejoDept : (drawingObj ? drawingObj.dept : ''));

    // Check if drawingObj requester department matches
    let reqDeptCode = '';
    if (drawingObj && state.users) {
        const reqUser = state.users.find(u => checkIsRequester(u.username) || checkIsRequester(u.fullname) || u.username === drawingObj.requester || u.fullname === drawingObj.requester || u.username === drawingObj.uploader || u.fullname === drawingObj.uploader);
        if (reqUser) {
            reqDeptCode = normalizeDepartmentCode(reqUser.dept);
            if (!reqDeptCode && reqUser.role) {
                const parts = reqUser.role.toUpperCase().split(/[\s_]+/);
                const codePart = parts.find(p => p !== 'USER' && p !== 'STAFF' && p.length >= 2);
                if (codePart) reqDeptCode = normalizeDepartmentCode(codePart);
            }
        }
    }

    // Match conditions
    if (userDeptCode && targetDeptCode && userDeptCode === targetDeptCode) return true;
    if (userDeptCode && reqDeptCode && userDeptCode === reqDeptCode) return true;
    if (targetDeptCode && role.toUpperCase().includes(targetDeptCode)) return true;
    if (reqDeptCode && role.toUpperCase().includes(reqDeptCode)) return true;

    return false;
}

function canManageSparePartAllocation(role) {
    return role === 'Drafter' || isLeadRole(role);
}

// ponytail: helper to format engineer name with role / discipline (e.g., "Thorik (Elektrik)", "Rifan Nur Satriyo (Drafter - Mekanikal)")
function formatEngineerDisplay(engineerName) {
    if (!engineerName || typeof engineerName !== 'string') return '-';
    const raw = engineerName.trim();
    if (!raw || ['unassigned', 'belum ditentukan', 'belum ada', '-', 'n/a', 'none'].includes(raw.toLowerCase())) {
        return 'Unassigned';
    }

    // Support comma-separated engineers
    const names = raw.split(',').map(n => n.trim()).filter(Boolean);
    const formatted = names.map(name => {
        const engUser = (state.users || []).find(u =>
            (u.fullname && u.fullname.toLowerCase() === name.toLowerCase()) ||
            (u.username && u.username.toLowerCase() === name.toLowerCase())
        );

        if (!engUser) {
            const listObj = engineersList.find(e => e.name && e.name.toLowerCase() === name.toLowerCase());
            if (listObj && (listObj.role || listObj.section)) {
                const sub = listObj.section || listObj.role;
                return `${name} (${sub})`;
            }
            return name;
        }

        const role = engUser.role || '';
        const sec = engUser.section || '';
        
        let label = '';
        if (sec && role && role !== sec) {
            label = `${sec}`;
        } else if (sec) {
            label = sec;
        } else if (role) {
            label = role;
        }

        return label ? `${engUser.fullname || name} (${label})` : (engUser.fullname || name);
    });

    return formatted.join(', ');
}


// ponytail: helper to check if a user is a non-Engineering Supervisor or Manager
function isNonEngSpvOrManager(userOrRole, deptInput) {
    let user = null;
    let role = '';
    let dept = '';
    if (userOrRole && typeof userOrRole === 'object') {
        user = userOrRole;
        role = user.role || '';
        dept = user.dept || '';
    } else {
        user = state.currentUser;
        role = userOrRole || (user ? user.role : '');
        dept = deptInput || (user ? user.dept : '');
    }

    if (!role) return false;
    if (role === 'Server' || (user && user.username === 'server')) return false;

    const engAdminRoles = ['Supervisor Eng', 'Manager Eng', 'Plant Manager', 'Factory Manager', 'Foreman Eng', 'Admin Eng'];
    if (engAdminRoles.includes(role)) return false;

    const normalizedDept = typeof normalizeDepartmentCode === 'function' ? normalizeDepartmentCode(dept) : String(dept || '').toUpperCase();
    const isEngDept = normalizedDept === 'ENG' || / eng$/i.test(role) || / eng /i.test(role);
    if (isEngDept) return false;

    const isSpvOrManager = role === 'Supervisor' || role === 'Manager' ||
        role.startsWith('Supervisor ') || role.startsWith('Manager ') ||
        role.startsWith('SPV ') || role === 'SPV' || role === 'spv_user' ||
        role === 'manager_user' || role === 'spv_dept' || role === 'manager_dept' ||
        /spv|supervisor|manager/i.test(role);

    return isSpvOrManager;
}

// ponytail: helper to check if a user is limited to 2 active General EJO / Drawing EJO (User role & non-ENG SPV/Manager)
function isUserLimited(userOrRole, deptInput) {
    let user = null;
    let role = '';
    let dept = '';
    if (userOrRole && typeof userOrRole === 'object') {
        user = userOrRole;
        role = user.role || '';
        dept = user.dept || '';
    } else {
        user = state.currentUser;
        role = userOrRole || (user ? user.role : '');
        dept = deptInput || (user ? user.dept : '');
    }

    if (!role) return false;
    return isOrdinaryUser(role) || isNonEngSpvOrManager(user, dept);
}

// ponytail: helper to check if a user is authorized to review & manage Engineering Projects (only Admin Eng, Foreman Eng, Drafters, Engineer Eng, Server; strictly excluding all non-ENG users/staff/SPV/Managers)
function canUserReviewProject(userOrRole) {
    let user = null;
    let role = '';
    if (userOrRole && typeof userOrRole === 'object') {
        user = userOrRole;
        role = user.role || '';
    } else {
        user = state.currentUser;
        role = userOrRole || (user ? user.role : '');
    }
    if (!role) return false;
    const username = (user ? user.username : (state.currentUser ? state.currentUser.username : '') || '').toLowerCase().trim();
    if (role === 'Server' || username === 'server' || username === 'admin') return true;
    if (isForemanAdminRole(role)) return true;
    if (isNonEngSpvOrManager(user)) return false;
    if (isOrdinaryUser(role)) return false;

    const dept = (user ? (user.dept || user.department || '') : (state.currentUser ? (state.currentUser.dept || state.currentUser.department || '') : '')).toUpperCase();
    const isEngRole = DRAFTER_ROLES.includes(role) || role === 'Supervisor Eng' || role === 'Manager Eng' || role === 'Staff ENG' || role === 'User ENG' || dept === 'ENG' || (typeof getUserDepartmentCode === 'function' && getUserDepartmentCode() === 'ENG');
    return isEngRole;
}

// ponytail: helper to check if a user is authorized to access/view Admin Panel (only Foreman Eng, Admin Eng & Server; strictly hiding from Supervisor Eng, Manager Eng, and all SPV/Manager/FM/PM roles)
function canAccessAdminPanel(userOrRole, deptInput) {
    let role = '';
    let dept = '';
    if (userOrRole && typeof userOrRole === 'object') {
        role = userOrRole.role || '';
        dept = userOrRole.dept || '';
    } else {
        role = userOrRole || '';
        dept = deptInput || (state.currentUser ? state.currentUser.dept : '');
    }

    if (!role) return false;
    if (role === 'Server' || (state.currentUser && state.currentUser.username === 'server')) return true;

    // Sembunyikan Admin Panel untuk Factory Manager dan Plant Manager
    if (role === 'Factory Manager' || role === 'Plant Manager') return false;

    // Sembunyikan Admin Panel secara khusus untuk Supervisor Eng dan Manager Eng serta seluruh SPV & Manager
    const isSpvOrManagerRole = ['Supervisor Eng', 'Manager Eng', 'SPV Eng', 'Supervisor Engineering', 'Manager Engineering', 'Supervisor', 'Manager', 'SPV', 'spv_user', 'manager_user', 'spv_dept', 'manager_dept'].includes(role) ||
        role.startsWith('Supervisor ') || role.startsWith('Manager ') || role.startsWith('SPV ') ||
        /spv|supervisor|manager/i.test(role);

    if (isSpvOrManagerRole) {
        return false;
    }

    const engAdminRoles = ['Foreman Eng', 'Admin Eng'];
    if (engAdminRoles.includes(role)) return true;

    return false;
}

// ponytail: helper to count active EJOs assigned to a user (standard EJOs + general EJOs + drawings)
function getActiveEjoCountForUser(fullname) {
    const userLower = (fullname || '').trim().toLowerCase();
    if (!userLower) return 0;

    const isInactive = (item) => {
        if (!item) return true;
        const status = (item.status || '').trim().toLowerCase();
        return status === 'completed' ||
            status === 'cancelled' ||
            status === 'archived' ||
            status === 'rejected' ||
            status === 'done' ||
            item.is_archived === 1 ||
            item.is_archived === '1';
    };

    const isUserAssigned = (item) => {
        if (!item) return false;
        const engStr = (item.engineer || item.drafter || '').trim();
        if (!engStr) return false;
        const engineers = engStr.split(',').map(name => name.trim().toLowerCase());
        return engineers.includes(userLower);
    };

    const activeItemIds = new Set();

    (state.ejos || []).forEach(e => {
        if (!isInactive(e) && isUserAssigned(e)) {
            activeItemIds.add(e.id || ('ejo_' + Math.random()));
        }
    });

    (state.generalEjos || []).forEach(g => {
        if (!isInactive(g) && isUserAssigned(g)) {
            activeItemIds.add(g.id || ('gejo_' + Math.random()));
        }
    });

    (state.drawings || []).forEach(d => {
        if (!isInactive(d) && isUserAssigned(d)) {
            activeItemIds.add(d.id || ('drw_' + Math.random()));
        }
    });

    return activeItemIds.size;
}

// ponytail: helper to apply sidebar layout & display rules based on user role
function applySidebarRoleRestrictions() {
    if (!state.currentUser) return;

    const role = state.currentUser.role;
    const isTechNonDrafter = isDrafterRole(role) && role !== 'Drafter';

    // ponytail: Hide/show partlist cost saving charts based on user roles
    const partlistChartsGrid = document.getElementById("partlist-charts-grid");
    if (partlistChartsGrid) {
        const HIDDEN_ROLES = ['Sipil', 'Mekanik', 'Elektrik', 'Program', 'Kalibrasi', 'Repair Part', 'User', 'user_PRD', 'user_ENG', 'user_EPR', 'user_GA', 'user_QC', 'user_WRH', 'user_TMB', 'user_EUT', 'User PRD', 'User ENG', 'User EPR', 'User GA', 'User QC', 'User WRH', 'User TMB', 'User EUT', 'Staff PRD', 'Staff ENG', 'Staff EPR', 'Staff GA', 'Staff QC', 'Staff WRH', 'Staff TMB', 'Staff EUT'];
        if (HIDDEN_ROLES.includes(role)) {
            partlistChartsGrid.style.display = 'none';
        } else {
            partlistChartsGrid.style.display = 'grid';
        }
    }

    const sparePartToggleBtn = document.getElementById("btn-toggle-new-sparepart");
    const sparePartFormContainer = document.getElementById("sparepart-form-container");
    const canManageSparePart = canManageSparePartAllocation(role);
    if (sparePartToggleBtn) {
        sparePartToggleBtn.style.display = canManageSparePart ? 'inline-flex' : 'none';
    }
    if (sparePartFormContainer && !canManageSparePart) {
        sparePartFormContainer.style.display = 'none';
    }

    // ponytail: Hide overview button & import drawing button for Drafter roles, Ordinary users (Staff/User), and Dept SPV/Manager (non-ENG SPV & Manager)
    const isDeptSpvOrManager = isNonEngSpvOrManager(state.currentUser);

    const overviewBtn = document.querySelector('.nav-btn[data-tab="overview"]');
    if (overviewBtn) {
        overviewBtn.style.display = (isDrafterRole(role) || isOrdinaryUser(role) || isDeptSpvOrManager) ? 'none' : 'flex';
    }

    const importDrawingBtn = document.getElementById("btn-toggle-import-drawing");
    if (importDrawingBtn) {
        if (canUserImportDrawing(state.currentUser)) {
            importDrawingBtn.style.display = 'inline-flex';
        } else {
            importDrawingBtn.style.setProperty('display', 'none', 'important');
        }
    }

    // 2. Hide/show EJO limit & actions container based on role
    const limitContainerEl = document.getElementById("gejo-limit-container");
    const controlBarEl = document.querySelector("#tab-general-ejo .control-bar");
    const isTechStaff = isDrafterRole(role) || role === 'user_ENG' || role === 'Staff ENG' || role === 'User ENG' || (role || '').startsWith('Staff ENG');
    if (isTechStaff) {
        if (limitContainerEl) limitContainerEl.style.setProperty('display', 'none', 'important');
        if (controlBarEl) controlBarEl.style.gridTemplateColumns = '';
        const gejoCreateBtn = document.getElementById("gejo-btn-quick-new");
        if (gejoCreateBtn) gejoCreateBtn.style.setProperty('display', 'none', 'important');
    } else {
        if (limitContainerEl) limitContainerEl.style.display = 'flex';
        if (controlBarEl) controlBarEl.style.gridTemplateColumns = '';
        const gejoCreateBtn = document.getElementById("gejo-btn-quick-new");
        if (gejoCreateBtn) {
            gejoCreateBtn.style.display = checkGeneralEjoLimit() ? 'none' : 'flex';
        }
    }

    // 3. Hide/show admin panel button based on role
    const adminBtn = document.getElementById("nav-admin-btn");
    if (adminBtn) {
        if (canAccessAdminPanel(state.currentUser)) {
            adminBtn.style.removeProperty('display');
            adminBtn.style.display = 'flex';
        } else {
            adminBtn.style.setProperty('display', 'none', 'important');
        }
    }

    // 4. Handle EJO dropdown hierarchy and submenu based on roles
    const btnNavGeneralEjo = document.getElementById("btn-nav-general-ejo");
    const btnNavDrawing = document.getElementById("btn-nav-drawing");
    const btnNavProjects = document.getElementById("btn-nav-projects");
    const btnNavDrawingGallery = document.getElementById("btn-nav-drawing-gallery");
    const repairPartsBtn = document.querySelector('.sidebar-nav .nav-btn[data-tab="partlist"]');
    const galleryBtn = document.getElementById("btn-nav-partlist-gallery");

    const wrapperGeneralEjo = btnNavGeneralEjo ? btnNavGeneralEjo.closest('.nav-item-wrapper') : null;
    const wrapperDrawing = btnNavDrawing ? btnNavDrawing.closest('.nav-item-wrapper') : null;
    const wrapperProjects = btnNavProjects ? btnNavProjects.closest('.nav-item-wrapper') : null;
    const wrapperDrawingGallery = btnNavDrawingGallery ? btnNavDrawingGallery.closest('.nav-item-wrapper') : null;

    function setNavVisibility(btn, wrapper, visible) {
        if (btn) btn.style.display = visible ? 'flex' : 'none';
        if (wrapper) wrapper.style.display = visible ? '' : 'none';
    }

    const isStaffUser = role === 'User' || (role || '').includes('Staff') || isOrdinaryUser(role);
    // ponytail: hide projects nav for non-ENG SPV & Manager
    const showProjectsNav = !isStaffUser && !isDeptSpvOrManager && (isLeadRole(role) || role === 'Foreman Eng' || role === 'Admin Eng' || role === 'Server');

    const userDept = (state.currentUser ? state.currentUser.department || '' : '').toUpperCase();
    const isEngRole = DRAFTER_ROLES.includes(role) || isForemanAdminRole(role) || role === 'Supervisor Eng' || role === 'Manager Eng' || role === 'Staff ENG' || role === 'User ENG' || role === 'Server' || userDept === 'ENG' || getUserDepartmentCode() === 'ENG';
    const isInternalEngUser = isEngRole && !isDeptSpvOrManager;

    if (role === 'Drafter') {
        setNavVisibility(btnNavGeneralEjo, wrapperGeneralEjo, false);
        setNavVisibility(btnNavDrawing, wrapperDrawing, true);
        setNavVisibility(btnNavProjects, wrapperProjects, false);
        if (repairPartsBtn) repairPartsBtn.style.display = 'flex';
        if (galleryBtn) galleryBtn.style.display = 'flex';
    } else if (isTechNonDrafter) {
        setNavVisibility(btnNavGeneralEjo, wrapperGeneralEjo, true);
        setNavVisibility(btnNavDrawing, wrapperDrawing, false);
        setNavVisibility(btnNavProjects, wrapperProjects, false);
        if (repairPartsBtn) repairPartsBtn.style.display = 'none';
        if (galleryBtn) galleryBtn.style.display = 'flex';
    } else {
        setNavVisibility(btnNavGeneralEjo, wrapperGeneralEjo, true);
        setNavVisibility(btnNavDrawing, wrapperDrawing, true);
        setNavVisibility(btnNavProjects, wrapperProjects, showProjectsNav);
        if (repairPartsBtn) repairPartsBtn.style.display = 'flex';
        if (galleryBtn) galleryBtn.style.display = 'none';
    }

    if (btnNavDrawingGallery && wrapperDrawingGallery) {
        setNavVisibility(btnNavDrawingGallery, wrapperDrawingGallery, true);
        btnNavDrawingGallery.style.removeProperty('display');
        wrapperDrawingGallery.style.removeProperty('display');
        btnNavDrawingGallery.style.display = 'flex';
    }

    if (!showProjectsNav) {
        setNavVisibility(btnNavProjects, wrapperProjects, false);
        if (btnNavProjects) btnNavProjects.style.setProperty('display', 'none', 'important');
        if (wrapperProjects) wrapperProjects.style.setProperty('display', 'none', 'important');
    }

    // ponytail: Allow History EJO tab for all users (including staff/user accounts) so they can view history of General EJO and Drawing EJO
    const historyBtn = document.querySelector('.sidebar-nav .nav-btn[data-tab="history"]');
    if (historyBtn) {
        historyBtn.style.display = 'flex';
        historyBtn.style.removeProperty('display');
    }
    const historyProjectBtn = document.querySelector('.sidebar-nav .nav-btn[data-tab="history"][data-history-type="project"]');
    if (historyProjectBtn) {
        if (isStaffUser || isOrdinaryUser(role) || isDeptSpvOrManager || !showProjectsNav) {
            historyProjectBtn.style.display = 'none';
            historyProjectBtn.style.setProperty('display', 'none', 'important');
        } else {
            historyProjectBtn.style.display = 'flex';
            historyProjectBtn.style.removeProperty('display');
        }
    }
    if (repairPartsBtn && (isOrdinaryUser(role) || isStaffUser || isDeptSpvOrManager)) {
        repairPartsBtn.style.display = 'none';
        repairPartsBtn.style.setProperty('display', 'none', 'important');
    }
    // ponytail: Galeri Spare Part bisa dilihat oleh semua role (Staff, User, SPV, Manager per dept)
    if (galleryBtn) {
        galleryBtn.style.removeProperty('display');
        galleryBtn.style.display = 'flex';
    }

    // ponytail: Sembunyikan Drawing Sipil & Drawing Mekanik di Galeri Drawing untuk semua user (karena filter kategori & dept sudah tersedia lengkap di control-bar)
    const drawingGallerySubBtns = document.querySelectorAll("#drawing-gallery-submenu .nav-btn[data-tab='drawing-gallery']");
    drawingGallerySubBtns.forEach(subBtn => {
        subBtn.style.setProperty('display', 'none', 'important');
    });

    const btnToggleProj = document.getElementById("btn-toggle-new-project");
    const projFormContainer = document.getElementById("project-form-container");
    if (btnToggleProj) {
        if (isOrdinaryUser(role) || isStaffUser) {
            btnToggleProj.style.display = 'none';
            if (projFormContainer) projFormContainer.style.display = 'none';
        } else {
            btnToggleProj.style.display = 'inline-flex';
        }
    }

    // ponytail: auto-fill and lock form department dropdowns for user's department
    applyUserDepartmentToFormSelect("gejo-form-dept");
    applyUserDepartmentToFormSelect("drawing-form-dept");
    applyUserDepartmentToFormSelect("part-ejo-dept");
    // ponytail: lock department filter for non-engineering staff (Staff, SPV per dept, Manager per dept) to their own department only; keep all departments unlocked for engineering team and global leads
    const isGlobalLead = isGlobalLeadUser();
    const userDeptCode = getUserDepartmentCode();
    const isEngTeam = userDeptCode === 'ENG' || (state.currentUser && isDrafterRole(state.currentUser.role));
    const filterSelects = [
        document.getElementById("gejo-filter-dept"),
        document.getElementById("drawing-filter-dept"),
        document.getElementById("proj-filter-dept")
    ];

    if (!isGlobalLead && !isEngTeam && userDeptCode && state.currentUser) {
        filterSelects.forEach(select => {
            if (select) {
                select.value = userDeptCode;
                select.disabled = true;
                const group = select.closest(".filter-group");
                if (group) group.style.display = "none";
            }
        });
    } else {
        filterSelects.forEach(select => {
            if (select) {
                select.disabled = false;
                const group = select.closest(".filter-group");
                if (group) group.style.display = "flex";
            }
        });
    }

    // ponytail: hide uploader filter for Staff users (Staff per dept)
    const uploaderFilterSelects = [
        document.getElementById("drawing-filter-uploader"),
        document.getElementById("drawing-history-filter-uploader")
    ];
    uploaderFilterSelects.forEach(select => {
        if (select) {
            const group = select.closest(".filter-group");
            if (group) {
                if (isStaffUser) {
                    group.style.display = "none";
                    select.value = "all";
                } else {
                    group.style.display = "";
                }
            }
        }
    });
}

// ponytail: helper to get allowed assignee roles based on logged-in user role
function getAllowedAssigneeRoles(currentUserRole) {
    if (currentUserRole === 'Foreman Eng') {
        return [...DRAFTER_ROLES, 'Admin Eng'];
    } else if (currentUserRole === 'Supervisor Eng') {
        return ['Foreman Eng', ...DRAFTER_ROLES, 'Admin Eng'];
    } else if (currentUserRole === 'Manager Eng' || currentUserRole === 'Plant Manager') {
        return ['Supervisor Eng', 'Foreman Eng', ...DRAFTER_ROLES, 'Admin Eng'];
    } else {
        // Admin or Server can assign to anyone (except Server which is filtered globally)
        return ['Manager Eng', 'Plant Manager', 'Supervisor Eng', 'Foreman Eng', ...DRAFTER_ROLES, 'Admin Eng'];
    }
}

