    function populateApprovedDrawingsSelect() {
        const select = document.getElementById("proj-drawing-select");
        if (!select) return;

        select.innerHTML = '<option value="">-- Pilih Drawing EJO yang Selesai --</option>';

        const approvedDrawings = (state.drawings || []).filter(d => {
            const status = (d.status || '').toLowerCase();
            const hasFmSig = d.approvals && (d.approvals.factory_manager || d.approvals['factory_manager']);
            const hasManagerSig = d.approvals && (d.approvals.manager || d.approvals.manager_eng);
            const cat = (d.etiket_category || d.category || '').toLowerCase();
            const isMekanikPart = !cat.includes('sipil');
            return status === 'completed' || status === 'approved' || hasFmSig || (isMekanikPart && hasManagerSig);
        });

        if (approvedDrawings.length === 0) {
            const opt = document.createElement("option");
            opt.value = "";
            opt.textContent = "Belum ada Drawing EJO yang selesai";
            opt.disabled = true;
            select.appendChild(opt);
            return;
        }

        approvedDrawings.forEach(d => {
            const opt = document.createElement("option");
            opt.value = d.id;
            opt.textContent = `${d.id} - ${d.title || 'Drawing EJO'} (${d.ejo_id || 'Umum'})`;
            select.appendChild(opt);
        });
    }
