        // Trim transparent whitespace from canvas for perfect crop
        function getTrimmedSignatureDataUrl() {
            const rawW = canvas.width;
            const rawH = canvas.height;
            const imgData = ctx.getImageData(0, 0, rawW, rawH);
            const data = imgData.data;

            let minX = rawW, minY = rawH, maxX = 0, maxY = 0;
            let found = false;

            for (let y = 0; y < rawH; y++) {
                for (let x = 0; x < rawW; x++) {
                    const alpha = data[(y * rawW + x) * 4 + 3];
                    if (alpha > 10) { // non-transparent pixel
                        if (x < minX) minX = x;
                        if (x > maxX) maxX = x;
                        if (y < minY) minY = y;
                        if (y > maxY) maxY = y;
                        found = true;
                    }
                }
            }

            if (!found) return null;

            // Add margin padding (in DPR pixels)
            const pad = Math.round(16 * dpr);
            minX = Math.max(0, minX - pad);
            minY = Math.max(0, minY - pad);
            maxX = Math.min(rawW, maxX + pad);
            maxY = Math.min(rawH, maxY + pad);

            const cropW = maxX - minX;
            const cropH = maxY - minY;

            const cropCanvas = document.createElement("canvas");
            cropCanvas.width = cropW;
            cropCanvas.height = cropH;
            const cropCtx = cropCanvas.getContext("2d", { willReadFrequently: true });

            cropCtx.drawImage(canvas, minX, minY, cropW, cropH, 0, 0, cropW, cropH);
            return cropCanvas.toDataURL("image/png");
        }

