                { bg: 'rgba(233, 213, 255, 0.85)', border: '#e9d5ff' },  // Lilac Pucat Bersinar (Purple 200)
                { bg: 'rgba(217, 70, 239, 0.85)', border: '#d946ef' },  // Fuchsia Purple Terang (Fuchsia 500)
                { bg: 'rgba(88, 28, 135, 0.85)', border: '#581c87' }   // Ungu Sangat Gelap (Purple 900)
