// ponytail: update etiket modal preview images dynamically on category select change using converted PDF PNGs
function updateEtiketModalPreviews() {
    const etiketSelect = document.getElementById("drawing-upload-complete-etiket-category");
    if (!etiketSelect) return;

    const cat = etiketSelect.value || "Mekanik / Part";

    const badge = document.getElementById("etiket-category-badge");
    if (badge) badge.textContent = cat;

    const isSipil = cat.toLowerCase().includes('sipil');
    const landscapeImg = isSipil ? '/etiket/pak diki etiket landscape.png' : '/etiket/pak rifan etiket landscape.png';
    const portraitImg = isSipil ? '/etiket/pak diki etiket potrait.png' : '/etiket/pak rifan etiket potrait.png';

    const landscapeBox = document.getElementById("etiket-sample-landscape-preview");
    const portraitBox = document.getElementById("etiket-sample-portrait-preview");

    if (landscapeBox) {
        landscapeBox.innerHTML = `<img src="${encodeURI(landscapeImg)}" style="width: 100%; height: 100%; object-fit: contain; background: #ffffff;" alt="Sample Landscape ${cat}" />`;
    }
    if (portraitBox) {
        portraitBox.innerHTML = `<img src="${encodeURI(portraitImg)}" style="width: 100%; height: 100%; object-fit: contain; background: #ffffff;" alt="Sample Portrait ${cat}" />`;
    }
}

// ponytail: open zoom modal for detailed etiket sample review displaying Pak Diki's actual drawing
function openEtiketZoomModal(orientation) {
    const etiketSelect = document.getElementById("drawing-upload-complete-etiket-category");
    const cat = etiketSelect ? etiketSelect.value : "Mekanik / Part";

    const zoomModal = document.getElementById("etiket-zoom-modal");
    const zoomTitle = document.getElementById("etiket-zoom-title");
    const zoomBody = document.getElementById("etiket-zoom-body");
    const zoomDesc = document.getElementById("etiket-zoom-desc");

    if (!zoomModal || !zoomBody) return;

    const isSipil = cat.toLowerCase().includes('sipil');
    const imgPath = isSipil
        ? (orientation === 'landscape' ? '/etiket/pak diki etiket landscape.png' : '/etiket/pak diki etiket potrait.png')
        : (orientation === 'landscape' ? '/etiket/pak rifan etiket landscape.png' : '/etiket/pak rifan etiket potrait.png');
    const pdfPath = isSipil
        ? (orientation === 'landscape' ? '/etiket/pak diki etiket landscape.pdf' : '/etiket/pak diki etiket potrait.pdf')
        : (orientation === 'landscape' ? '/etiket/pak rifan etiket landscape.pdf' : '/etiket/pak rifan etiket potrait.pdf');
    const authorName = isSipil ? 'Diki (Sipil)' : 'Rifan (Mekanik)';

    const orientName = orientation === 'landscape' ? 'Landscape (Horizontal)' : 'Portrait (Vertikal)';
    if (zoomTitle) zoomTitle.textContent = `Sampel Etiket ${cat} (${orientation})`;

    zoomBody.innerHTML = `
        <div style="display: flex; flex-direction: column; align-items: center; justify-content: center; width: 100%; height: 100%; min-height: 0; padding: 6px; box-sizing: border-box; background: #ffffff; border-radius: 6px;">
            <img src="${encodeURI(imgPath)}" style="max-width: 100%; max-height: 100%; width: auto; height: auto; object-fit: contain; border-radius: 4px; box-shadow: 0 4px 15px rgba(0,0,0,0.15);" alt="Sampel Etiket ${cat} ${orientName}" />
        </div>
    `;

    if (zoomDesc) {
        zoomDesc.innerHTML = `
            <div style="display: flex; gap: 8px; align-items: center; flex-wrap: wrap;">
                <a href="${encodeURI(pdfPath)}" target="_blank" class="btn btn-sm btn-outline" style="padding: 4px 10px; font-size: 0.78rem; text-decoration: none; display: inline-flex; align-items: center; gap: 5px; background: rgba(6,182,212,0.1); color: var(--color-cyan, #06b6d4); border-color: rgba(6,182,212,0.3);">
                    📄 Lihat File PDF Original (${authorName})
                </a>
            </div>
        `;
    }

    zoomModal.style.display = 'flex';
    if (typeof lucide !== 'undefined') lucide.createIcons();
}

function closeEtiketZoomModal() {
    const zoomModal = document.getElementById("etiket-zoom-modal");
    if (zoomModal) zoomModal.style.display = 'none';
}

// ponytail: Show modal to upload a drawing and complete the work
async function triggerCardDrawingCompleteUpload(drawingId) {
    const hasSig = await ensureUserProfileSignature("penyelesaian dan pengiriman file drawing");
    if (!hasSig) {
        return;
    }
    return new Promise((resolve) => {
        const modal = document.getElementById("drawing-upload-complete-modal");
        const fileInput = document.getElementById("drawing-upload-complete-file-input");
        const trigger = document.getElementById("drawing-upload-complete-trigger");
        const filenameSpan = document.getElementById("drawing-upload-complete-filename");
        const preview = document.getElementById("drawing-upload-complete-preview");
        const previewImg = document.getElementById("drawing-upload-complete-preview-img");
        const btnOk = document.getElementById("drawing-upload-complete-btn-ok");
        const btnCancel = document.getElementById("drawing-upload-complete-btn-cancel");

        if (!modal || !fileInput || !trigger || !filenameSpan || !btnOk || !btnCancel) {
            // fallback if elements are not found
            triggerCardDrawingUpload(drawingId);
            resolve();
            return;
        }

        // Reset inputs
        fileInput.value = "";
        filenameSpan.textContent = "Pilih file Drawing (PDF/Gambar)";
        filenameSpan.style.color = "var(--text-secondary)";
        if (preview) preview.style.display = "none";
        if (previewImg) previewImg.src = "";

        const fileErrorDiv = document.getElementById("drawing-upload-complete-file-error");
        if (fileErrorDiv) fileErrorDiv.style.display = "none";
        delete trigger.dataset.hasError;
        trigger.style.borderColor = "rgba(6, 182, 212, 0.3)";
        trigger.style.background = "rgba(6, 182, 212, 0.02)";

        let selectedOrientation = 'landscape';
        const currentDrawing = (state.drawings || []).find(d => String(d.id) === String(drawingId));
        if (currentDrawing && currentDrawing.etiket_orientation) {
            selectedOrientation = currentDrawing.etiket_orientation;
        }

        const etiketSelect = document.getElementById("drawing-upload-complete-etiket-category");
        if (etiketSelect) {
            if (currentDrawing && (currentDrawing.category === "Sipil" || currentDrawing.etiket_category === "Sipil")) {
                etiketSelect.value = "Sipil";
            } else {
                etiketSelect.value = "Mekanik / Part";
            }
            etiketSelect.onchange = updateEtiketModalPreviews;
        }

        // Helper to update active visual highlight on Landscape vs Portrait cards
        const landscapeCard = document.getElementById("etiket-sample-card-landscape");
        const portraitCard = document.getElementById("etiket-sample-card-portrait");
        const landscapeBadge = document.getElementById("etiket-landscape-badge");
        const portraitBadge = document.getElementById("etiket-portrait-badge");

        const updateOrientationCardSelection = (orient) => {
            selectedOrientation = orient;
            if (landscapeCard) {
                if (orient === 'landscape') {
                    landscapeCard.style.border = "2px solid var(--color-cyan, #06b6d4)";
                    landscapeCard.style.background = "rgba(6, 182, 212, 0.12)";
                    landscapeCard.style.boxShadow = "0 0 12px rgba(6, 182, 212, 0.25)";
                    if (landscapeBadge) {
                        landscapeBadge.textContent = "✓ Terpilih";
                        landscapeBadge.style.background = "var(--color-cyan, #06b6d4)";
                        landscapeBadge.style.color = "#ffffff";
                        landscapeBadge.style.fontWeight = "700";
                    }
                } else {
                    landscapeCard.style.border = "1px solid rgba(255, 255, 255, 0.12)";
                    landscapeCard.style.background = "rgba(255, 255, 255, 0.03)";
                    landscapeCard.style.boxShadow = "none";
                    if (landscapeBadge) {
                        landscapeBadge.textContent = "Pilih";
                        landscapeBadge.style.background = "rgba(255, 255, 255, 0.05)";
                        landscapeBadge.style.color = "var(--text-tertiary, #9ca3af)";
                        landscapeBadge.style.fontWeight = "500";
                    }
                }
            }
            if (portraitCard) {
                if (orient === 'portrait') {
                    portraitCard.style.border = "2px solid var(--color-cyan, #06b6d4)";
                    portraitCard.style.background = "rgba(6, 182, 212, 0.12)";
                    portraitCard.style.boxShadow = "0 0 12px rgba(6, 182, 212, 0.25)";
                    if (portraitBadge) {
                        portraitBadge.textContent = "✓ Terpilih";
                        portraitBadge.style.background = "var(--color-cyan, #06b6d4)";
                        portraitBadge.style.color = "#ffffff";
                        portraitBadge.style.fontWeight = "700";
                    }
                } else {
                    portraitCard.style.border = "1px solid rgba(255, 255, 255, 0.12)";
                    portraitCard.style.background = "rgba(255, 255, 255, 0.03)";
                    portraitCard.style.boxShadow = "none";
                    if (portraitBadge) {
                        portraitBadge.textContent = "Pilih";
                        portraitBadge.style.background = "rgba(255, 255, 255, 0.05)";
                        portraitBadge.style.color = "var(--text-tertiary, #9ca3af)";
                        portraitBadge.style.fontWeight = "500";
                    }
                }
            }
        };

        // Wire card click events to select orientation directly
        if (landscapeCard) {
            landscapeCard.onclick = () => updateOrientationCardSelection('landscape');
        }
        if (portraitCard) {
            portraitCard.onclick = () => updateOrientationCardSelection('portrait');
        }

        // Apply initial orientation card highlight
        updateOrientationCardSelection(selectedOrientation);

        // Render initial etiket previews
        updateEtiketModalPreviews();

        const zoomCloseBtn = document.getElementById("etiket-zoom-close");
        if (zoomCloseBtn) zoomCloseBtn.onclick = closeEtiketZoomModal;

        const zoomModal = document.getElementById("etiket-zoom-modal");
        if (zoomModal) {
            zoomModal.onclick = (e) => {
                if (e.target === zoomModal) closeEtiketZoomModal();
            };
        }

        const handleTriggerClick = () => {
            fileInput.click();
        };

        trigger.removeEventListener("click", handleTriggerClick);
        trigger.addEventListener("click", handleTriggerClick);

        const handleFileChange = (e) => {
            const file = e.target.files[0];
            if (file) {
                const allowedExtensions = ['.pdf', '.jpg', '.jpeg', '.png', '.webp'];
                const fileExtension = '.' + file.name.split('.').pop().toLowerCase();
                if (!allowedExtensions.includes(fileExtension)) {
                    showToast("Format file tidak didukung! Hanya file PDF atau gambar (JPG, JPEG, PNG, WEBP) yang diperbolehkan.", "error");
                    fileInput.value = "";
                    filenameSpan.textContent = "Pilih file Drawing (PDF/Gambar)";
                    filenameSpan.style.color = "var(--text-secondary)";
                    if (preview) preview.style.display = "none";
                    if (previewImg) previewImg.src = "";
                    return;
                }

                if (fileErrorDiv) fileErrorDiv.style.display = "none";
                delete trigger.dataset.hasError;
                trigger.style.borderColor = "rgba(6, 182, 212, 0.3)";
                trigger.style.background = "rgba(6, 182, 212, 0.02)";

                filenameSpan.textContent = file.name;
                filenameSpan.style.color = "var(--text-primary)";

                if (file.type.startsWith("image/") && preview && previewImg) {
                    const reader = new FileReader();
                    reader.onload = (event) => {
                        previewImg.src = event.target.result;
                        preview.style.display = "flex";
                    };
                    reader.readAsDataURL(file);
                } else if (preview) {
                    preview.style.display = "none";
                }
            }
        };

        fileInput.removeEventListener("change", handleFileChange);
        fileInput.addEventListener("change", handleFileChange);

        modal.style.display = 'flex';
        lucide.createIcons();

        const cleanUp = () => {
            modal.style.display = 'none';
            fileInput.removeEventListener("change", handleFileChange);
            trigger.removeEventListener("click", handleTriggerClick);
            // Replace buttons with clones to remove previous event listeners
            btnOk.replaceWith(btnOk.cloneNode(true));
            btnCancel.replaceWith(btnCancel.cloneNode(true));
        };

        // Re-get buttons after replacement to add listener
        document.getElementById("drawing-upload-complete-btn-cancel").addEventListener("click", () => {
            cleanUp();
            resolve(false);
        });

        document.getElementById("drawing-upload-complete-btn-ok").addEventListener("click", async () => {
            const file = fileInput.files[0];
            if (!file) {
                showToast("Harap pilih/unggah file drawing terlebih dahulu!", "error");
                if (fileErrorDiv) {
                    fileErrorDiv.style.display = "flex";
                    if (typeof lucide !== 'undefined') lucide.createIcons();
                }
                trigger.dataset.hasError = "true";
                trigger.style.borderColor = "#ef4444";
                trigger.style.background = "rgba(239, 68, 68, 0.08)";
                trigger.style.animation = "none";
                trigger.offsetHeight; // trigger reflow
                trigger.style.animation = "shake 0.4s ease-in-out";
                return;
            }

            const selectedEtiket = etiketSelect ? etiketSelect.value : "Mekanik / Part";
            showToast("Mengunggah file drawing...", "info");
            const fd = new FormData();
            fd.append("file", file);
            fd.append("uploader", state.currentUser ? state.currentUser.fullname : "");
            fd.append("category", selectedEtiket);
            fd.append("etiket_category", selectedEtiket);
            fd.append("etiket_orientation", selectedOrientation);

            try {
                const res = await fetch(`/api/drawings/${drawingId}`, {
                    method: "PUT",
                    body: fd
                });
                if (!res.ok) {
                    let errMsg = "Gagal mengunggah file drawing";
                    try {
                        const errData = await res.json();
                        if (errData && errData.message) {
                            errMsg = errData.message;
                        }
                    } catch (e) { }
                    throw new Error(errMsg);
                }

                showToast("File drawing berhasil diunggah!", "success");
                await initData();
                renderDrawings();

                cleanUp();
                resolve(true);

                // ponytail: setelah upload sukses, langsung trigger action completion
                setTimeout(() => {
                    moveDrawingStatus(drawingId, 'approve');
                }, 100);

            } catch (err) {
                console.error(err);
                showToast(err.message || "Gagal mengunggah file", "error");
            }
        });
    });
}

// ponytail: Helper to upload a drawing file directly from a Kanban board card
async function triggerCardDrawingUpload(drawingId) {
    const hasSig = await ensureUserProfileSignature("pengunggahan file drawing");
    if (!hasSig) {
        return;
    }
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.type = "file";
    fileInput.accept = "image/*,.pdf";

    fileInput.onchange = async () => {
        const file = fileInput.files[0];
        if (!file) return;

        const allowedExtensions = ['.pdf', '.jpg', '.jpeg', '.png', '.webp'];
        const fileExtension = '.' + file.name.split('.').pop().toLowerCase();
        if (!allowedExtensions.includes(fileExtension)) {
            showToast("Format file tidak didukung! Hanya file PDF atau gambar (JPG, JPEG, PNG, WEBP) yang diperbolehkan.", "error");
            return;
        }

        showToast("Mengunggah file drawing...", "info");

        const fd = new FormData();
        fd.append("file", file);
        fd.append("uploader", state.currentUser ? state.currentUser.fullname : "");

        try {
            const res = await fetch(`/api/drawings/${drawingId}`, {
                method: "PUT",
                body: fd
            });
            if (!res.ok) throw new Error("Gagal mengunggah file drawing");

            showToast("File drawing berhasil diunggah!", "success");
            await initData();
            renderDrawings();
        } catch (err) {
            console.error(err);
            showToast(err.message || "Gagal mengunggah file", "error");
        }
    };

    fileInput.click();
}

async function archiveDrawingCard(drawingId) {
    const confirmArchive = await showCustomConfirm(`Apakah Anda yakin ingin mengarsipkan drawing ${drawingId}?`);
    if (!confirmArchive) return;

    try {
        const now = new Date().toLocaleString('id-ID', { hour12: false }).replace(/\//g, '-');
        const uploaderName = state.currentUser ? state.currentUser.fullname : 'System';
        const newLog = {
            date: now,
            message: `Drawing diarsip oleh ${uploaderName}.`
        };

        const res = await fetch(`/api/drawings/${drawingId}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                status: 'Archived',
                is_archived: 1,
                logs: [newLog]
            })
        });
        if (!res.ok) throw new Error("Gagal mengarsipkan drawing");

        showToast("Drawing berhasil diarsipkan!", "success");
        await initData();
        renderDrawings();
    } catch (err) {
        showToast(err.message || "Gagal mengarsipkan drawing", "error");
    }
}

// ponytail: Helper to get action transition buttons for Drawing cards on the board, ensuring click propagation is stopped
function getDrawingCardActions(d) {
    const userRole = state.currentUser ? state.currentUser.role : '';
    const userFullname = state.currentUser ? state.currentUser.fullname : '';
    const username = state.currentUser ? state.currentUser.username : '';

    const isAssigned = state.currentUser && (
        checkIsAssigned(d.engineer, state.currentUser) ||
        checkIsAssigned(d.drafter, state.currentUser)
    );
    const isDrafter = isDrafterRole(userRole) || userRole === 'Drafter' || userRole === 'Drafter Eng' || userRole === 'Drafter/Engineer';

    const isForeman = userRole === 'Foreman Eng' || userRole === 'Admin Eng' || userRole === 'Server';
    const isSupervisor = userRole === 'Supervisor Eng' || userRole === 'Server';
    const isManager = userRole === 'Manager Eng' || userRole === 'Plant Manager' || userRole === 'Server';
    const isFactoryManager = userRole === 'Factory Manager' || userRole === 'Server';

    let buttons = '';

    const isUploader = state.currentUser && (d.uploader === state.currentUser.fullname || d.uploader === state.currentUser.username || d.requester === state.currentUser.fullname || d.requester === state.currentUser.username);

    if (d.status === 'Pending Dept Approval') {
        const isDeptApprover = isDepartmentApprover(state.currentUser, d.dept, d);
        const isServer = state.currentUser && (state.currentUser.role === 'Server' || state.currentUser.username === 'server');
        if (isDeptApprover || isServer) {
            buttons += `
                <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">Tolak</button>
                <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Setujui &rarr;</button>
            `;
        }
    } else if (d.status === 'Pending Foreman Approval') {
        const isPhase1 = (getDrawingPhase(d) === 1) || (!d.file_path);
        if (isPhase1) {
            if (isUploader) {
                buttons += `
                    <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); deleteDrawing('${d.id}')">Batal / Hapus</button>
                    <button class="btn btn-outline btn-xs" onclick="event.stopPropagation(); editDrawingByUser('${d.id}')">Edit</button>
                `;
            } else if (isForeman) {
                buttons += `
                    <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">Tolak</button>
                    <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Setujui &rarr;</button>
                `;
            }
        } else {
            // Official sign-off step (after Requester & Dept approval)
            if (isForeman) {
                buttons += `
                    <button class="btn btn-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">&larr; Tolak</button>
                    <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Setujui &rarr;</button>
                `;
            }
        }
    } else if (d.status === 'Checking') {
        if (isUploader) {
            buttons += `
                <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); deleteDrawing('${d.id}')">Batal / Hapus</button>
                <button class="btn btn-outline btn-xs" onclick="event.stopPropagation(); editDrawingByUser('${d.id}')">Edit</button>
            `;
        } else if (isForeman) {
            buttons += `
                <button class="btn btn-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">&larr; Balikkan</button>
                <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Mulai Kerja &rarr;</button>
            `;
        }
    } else if (d.status === 'On Progress') {
        // ponytail: Assigned Drafter or Foreman completes work and submits for Requester approval
        if (isAssigned || isForeman) {
            if (d.file_path) {
                buttons += `<button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Selesaikan &rarr;</button>`;
            } else {
                buttons += `
                    <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); triggerCardDrawingCompleteUpload('${d.id}')">Selesaikan &rarr;</button>
                `;
            }
        }
    } else if (d.status === 'Pending Requester Approval') {
        if (checkIsRequesterOrRole(d)) {
            buttons += `
                <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">Tolak</button>
                <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Setujui &rarr;</button>
            `;
        }
    } else if (d.status === 'Pending Supervisor Approval') {
        if (isSupervisor) {
            buttons += `
                <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">Tolak</button>
                <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Setujui &rarr;</button>
            `;
        }
    } else if (d.status === 'Pending Manager Approval') {
        if (isManager) {
            buttons += `
                <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">Tolak</button>
                <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Setujui &rarr;</button>
            `;
        }
    } else if (d.status === 'Pending Factory Manager Approval') {
        if (isFactoryManager) {
            buttons += `
                <button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'reject')">Tolak</button>
                <button class="btn btn-primary btn-xs" onclick="event.stopPropagation(); moveDrawingStatus('${d.id}', 'approve')">Setujui &rarr;</button>
            `;
        }
    } else if (d.status === 'Completed') {
        if (typeof isDrawingAutoArchiveDue === 'function' && isDrawingAutoArchiveDue(d)) return '';
        const isRequester = (userFullname === d.requester || userFullname === d.uploader || userRole === 'Admin Eng' || userRole === 'Server');
        if (isRequester || userRole === 'Foreman Eng') {
            buttons += `
                <button class="btn btn-primary btn-xs glow-button" onclick="event.stopPropagation(); archiveDrawingCard('${d.id}')">Konfirmasi Selesai & Arsipkan</button>
            `;
        }
    }

    const isServerUser = state.currentUser && (state.currentUser.role === 'Server' || state.currentUser.username === 'server' || userRole === 'Server' || getRoleLevel(userRole) === 100);
    if (isServerUser) {
        if (!buttons.includes(`deleteDrawing('${d.id}')`)) {
            buttons = `<button class="btn btn-danger-outline btn-xs" onclick="event.stopPropagation(); deleteDrawing('${d.id}')">Batal / Hapus</button> ` + buttons;
        }
    }

    // ponytail: Add "Detail" button across all drawing card actions instead of "Di Project"
    if (!buttons.includes(`openDrawingDetails('${d.id}')`)) {
        buttons += ` <button class="btn btn-outline btn-xs" onclick="event.stopPropagation(); openDrawingDetails('${d.id}')">Detail</button>`;
    }

    if (!buttons) {
        if (d.status === 'Completed') {
            return `<span class="text-xs text-green" style="font-weight: 500;"><i data-lucide="check-circle" style="width:12px;height:12px;display:inline-block;vertical-align:middle;margin-right:2px;"></i>Selesai</span>`;
        }
        if (d.status === 'Rejected') {
            return `<span class="text-xs text-red" style="font-weight: 500;">Ditolak</span>`;
        }
        return '';
    }

    return buttons;
}

// ponytail: Update General EJO status directly from Kanban card with a log entry and signature approval flow
async function moveGeneralEjoStatus(ejoId, nextStatus) {
    const ejo = getVisibleGeneralEjos().find(item => item.id === ejoId);
    if (!ejo) return;

    const oldStatus = ejo.status;
    let rejectionReason = "";
    let rejectionImage = null;
    let nextDescription = undefined;
    let rejectionSignature = null;
    let finalEstDate = ejo.estDate || "";

    // ponytail: rename Lead Engineer -> Foreman
    const isLead = state.currentUser && (isLeadRole(state.currentUser.role));
    const isAssigned = checkIsAssigned(ejo.engineer, state.currentUser);
    const isRequester = checkIsRequester(ejo.requester);
    const isForeman = state.currentUser && isForemanAdminRole(state.currentUser.role);

    const isDeptApprover = isDepartmentApprover(state.currentUser, ejo.dept);

    let canMove = false;
    if (nextStatus === 'Pending User Approval' || nextStatus === 'Completed') {
        const isCancelled = oldStatus && (oldStatus === 'Cancelled' || oldStatus.includes('Cancelled') || oldStatus.includes('Ditolak'));
        if (!isCancelled) {
            const isRepairPartCategory = ejo.category === 'Repair Part' || (ejo.category && ejo.category.toLowerCase().includes('repair'));
            if (isRepairPartCategory) {
                const isWorkConfirmed = parseInt(ejo.qty_work_confirmed) === 1;
                if (!isWorkConfirmed) {
                    showToast("Pekerjaan harus dikonfirmasi terlebih dahulu sebelum diselesaikan.", "error");
                    return;
                }
                const qVal = parseInt(ejo.quantity || 1);
                const qNeededTarget = (ejo.qty_needed_target !== undefined && ejo.qty_needed_target !== null && parseInt(ejo.qty_needed_target) > 0)
                    ? parseInt(ejo.qty_needed_target)
                    : ((ejo.qty_needed !== undefined && ejo.qty_needed !== null && parseInt(ejo.qty_needed) > 0) ? parseInt(ejo.qty_needed) : 1);
                const qStockTarget = (ejo.qty_stock_target !== undefined && ejo.qty_stock_target !== null && parseInt(ejo.qty_stock_target) > 0)
                    ? parseInt(ejo.qty_stock_target)
                    : Math.max(0, qVal - qNeededTarget);
                const totalTarget = Math.max(qVal, qNeededTarget + qStockTarget);

                const qNeeded = (ejo.qty_needed_actual !== undefined && ejo.qty_needed_actual !== null)
                    ? parseInt(ejo.qty_needed_actual)
                    : 0;
                const qStock = (ejo.qty_stock !== undefined && ejo.qty_stock !== null) ? parseInt(ejo.qty_stock) : 0;
                const totalInput = qNeeded + qStock;

                if (totalInput < totalTarget || (qNeededTarget > 0 && qNeeded < qNeededTarget) || (qStockTarget > 0 && qStock < qStockTarget)) {
                    showToast("Quantity mesin & stok harus terpenuhi sebelum menyelesaikan pekerjaan.", "error");
                    return;
                }
            }
        }
    }

    if (nextStatus === 'In Progress') {
        if (oldStatus === 'Approved' || oldStatus.startsWith('Checking')) {
            canMove = isForeman || isAssigned;
        } else if (oldStatus === 'Pending User Approval') canMove = isRequester;
        else if (oldStatus === 'Pending Foreman Approval') canMove = isForeman || isRequester;
    } else {
        if (oldStatus === 'Waiting Dept Approval') {
            if (nextStatus === 'Requested') {
                canMove = isDeptApprover;
            } else if (nextStatus === 'Cancelled') {
                canMove = isRequester || isDeptApprover;
            }
        } else if (oldStatus === 'Requested') {
            canMove = isForeman;
        } else if (oldStatus === 'Approved' || oldStatus.startsWith('Checking')) {
            canMove = isForeman;
        } else if (oldStatus.startsWith('In Progress') && nextStatus === 'Pending User Approval') {
            canMove = isForeman || isAssigned;
        } else if (oldStatus.startsWith('In Progress') && (nextStatus === 'Checking' || nextStatus === 'Requested')) {
            // ponytail: allow foreman/admin to revert in progress back to checking or requested
            canMove = isForeman;
        } else if (oldStatus === 'Pending User Approval' && (nextStatus === 'Completed' || nextStatus === 'Pending Foreman Approval')) {
            canMove = isRequester;
        } else if (oldStatus === 'Pending Foreman Approval' && nextStatus === 'Completed') {
            canMove = isForeman || isRequester;
        }
    }

    if (!canMove) {
        if (oldStatus.startsWith('In Progress') && nextStatus === 'Pending User Approval' && !isForeman && !isAssigned) {
            showToast("Hanya Engineer yang ditunjuk atau Foreman/Admin yang dapat menyelesaikan pekerjaan!", "error");
        } else if (oldStatus.startsWith('In Progress') && !isForeman) {
            showToast("Hanya Foreman ENG / Admin ENG yang dapat mengembalikan status ini!", "error");
        } else if (oldStatus === 'Pending User Approval' && !isRequester) {
            showToast("Hanya User (Requester) pemohon EJO yang dapat memproses status ini!", "error");
        } else if (oldStatus === 'Pending Foreman Approval' && !isForeman && !isRequester) {
            showToast("Hanya Foreman / Admin atau Requester yang dapat memproses status ini!", "error");
        } else {
            showToast("Anda tidak memiliki akses untuk memproses status ini!", "error");
        }
        return;
    }

    // ponytail: confirm start work or handle rejection routing
    let finalStatus = nextStatus;
    const approvalsObj = { ...(ejo.approvals || {}) };
    const now = new Date();
    const timestamp = now.getFullYear() + "-" +
        String(now.getMonth() + 1).padStart(2, '0') + "-" +
        String(now.getDate()).padStart(2, '0') + " " +
        String(now.getHours()).padStart(2, '0') + ":" +
        String(now.getMinutes()).padStart(2, '0');

    if (nextStatus === 'In Progress') {
        if (oldStatus === 'Approved' || oldStatus.startsWith('Checking')) {
            const confirmStart = await showCustomConfirm(
                "Apakah Anda sudah benar-benar mengecek pekerjaan ini dan siap untuk mulai bekerja?",
                "Konfirmasi Mulai Kerja"
            );
            if (!confirmStart) return;
        } else if (oldStatus.startsWith('Pending')) {
            // Build target routing options based on who is rejecting
            let options = [];
            const assignedEng = (ejo.engineer && ejo.engineer.trim() && ejo.engineer !== 'Unassigned') ? ejo.engineer.trim() : '';
            const inProgressLabel = assignedEng ? `Kembalikan ke Engineer (${assignedEng})` : 'Kembalikan ke Engineer (In Progress)';

            if (oldStatus === 'Pending Foreman Approval') {
                options = [
                    { value: 'In Progress', label: inProgressLabel }
                ];
            } else if (oldStatus === 'Pending User Approval') {
                options = [
                    { value: 'In Progress', label: inProgressLabel }
                ];
            }

            const rejectionResult = await showGeneralEjoRejectionModal(options);
            if (!rejectionResult) return; // Cancelled

            // ponytail: signature prompt disabled for General EJO
            finalStatus = rejectionResult.target;
            rejectionReason = rejectionResult.reason;
            rejectionImage = rejectionResult.image;
            rejectionSignature = null;

            // Handle revision status numbers if target is In Progress
            if (finalStatus === 'In Progress') {
                const revMatch = oldStatus.match(/\(Revisi \d+\)/);
                if (revMatch) {
                    finalStatus = `In Progress ${revMatch[0]}`;
                } else {
                    finalStatus = getPreviousInProgressStatus(ejo);
                }
            }

            // Clear approvals signatures depending on rejection target
            if (finalStatus.startsWith('In Progress') || finalStatus === 'Pending User Approval') {
                // Clear all
                for (let key in approvalsObj) delete approvalsObj[key];
                if (finalStatus.startsWith('In Progress')) {
                    const parsed = parseEjoDescription(ejo.description);
                    nextDescription = buildEjoDescription(parsed.descText, "", parsed.attachments);
                }
            } else if (finalStatus === 'Pending Foreman Approval') {
                delete approvalsObj.foreman;
            }
        }
    } else {
        // Approving: require signature upload
        if (oldStatus === 'Waiting Dept Approval' && nextStatus === 'Requested') {
            approvalsObj.dept_manager = {
                username: state.currentUser.username,
                name: state.currentUser.fullname,
                signature: "approved",
                date: timestamp
            };
        } else if (oldStatus === 'Pending User Approval' && (nextStatus === 'Completed' || nextStatus === 'Pending Foreman Approval')) {
            // ponytail: signature prompt disabled for General EJO
            approvalsObj.user = {
                username: state.currentUser.username,
                name: state.currentUser.fullname,
                signature: "approved",
                date: timestamp
            };
        } else if (oldStatus === 'Pending Foreman Approval' && nextStatus === 'Completed') {
            // ponytail: signature prompt disabled for General EJO
            approvalsObj.foreman = {
                username: state.currentUser.username,
                name: state.currentUser.fullname,
                signature: "approved",
                date: timestamp
            };
        }
    }

    // ponytail: custom popup modal for approving general EJO with engineer checkboxes and checking sub-status radios
    let finalEngineer = ejo.engineer || 'Unassigned';
    let finalTargetDate = ejo.targetDate;
    if (finalStatus === 'Approved' || finalStatus === 'Checking') {
        const approvalData = await showGeneralEjoApprovalModal(ejo);
        if (!approvalData) return; // User cancelled

        if (approvalData.engineers.length === 0) {
            showToast("Pekerjaan tidak dapat disetujui tanpa penugasan engineer!", "warning");
            return;
        }

        // ponytail: signature prompt disabled for General EJO
        rejectionSignature = null;

        // ponytail: upload drawing if Drawing Ready is checked
        if (approvalData.drawingFile) {
            try {
                await uploadDrawingFileDuringApproval(ejo, approvalData.drawingFile);
            } catch (err) {
                return; // Stop EJO approval if drawing upload fails
            }
        }

        finalEngineer = approvalData.engineers.join(', ');
        // ponytail: transition directly to In Progress on approval/assignment
        finalStatus = 'In Progress';
        finalEstDate = approvalData.estDate;
    } else if (finalStatus === 'Cancelled') {
        // ponytail: ask for reason on rejection/cancellation
        const reason = await showCustomPrompt(
            "Masukkan alasan penolakan/pembatalan EJO ini:",
            "",
            "Alasan Penolakan"
        );
        if (reason === null) return; // User cancelled
        if (reason.trim() === "") {
            showToast("Alasan penolakan wajib diisi!", "warning");
            return;
        }
        rejectionReason = reason.trim();
        rejectionSignature = null; // ponytail: signature prompt disabled for General EJO
    } else if (finalStatus === 'Requested' && oldStatus.startsWith('In Progress')) {
        // ponytail: signature prompt disabled for General EJO
        rejectionSignature = null;
        finalEngineer = 'Unassigned';
    }

    // ponytail: require explanation when completing a revised EJO or when Drafter/RestrictedCompleter completes EJO
    let completionReason = "";
    let completionSignature = null;
    const isDrafter = state.currentUser && isDrafterRole(state.currentUser.role);
    const isRestrictedCompleter = state.currentUser && ['Foreman Eng', 'Supervisor Eng', 'Manager Eng', 'Plant Manager'].includes(state.currentUser.role);

    if (oldStatus.startsWith("In Progress") && finalStatus === "Pending User Approval") {
        let completeData = null;
        if (oldStatus.includes("(Revisi ")) {
            const explanation = await showCustomPrompt(
                "Pekerjaan revisi ini memerlukan penjelasan penyelesaian. Silakan masukkan keterangan (apa saja yang direvisi & di bagian mana):",
                "",
                "Laporan Penyelesaian Revisi"
            );
            if (explanation === null) return; // User cancelled
            if (explanation.trim() === "") {
                showToast("Keterangan revisi wajib diisi untuk menyelesaikan pekerjaan!", "warning");
                return;
            }
            completeData = { message: explanation.trim(), attachments: (parseEjoDescription(ejo.description).attachments || []) };
        } else {
            if (isDrafter || isRestrictedCompleter) {
                const data = await showGeneralEjoCompletionModal(ejo);
                if (data === null) return; // User cancelled
                completeData = data;
            }
        }

        if (completeData) {
            completionReason = (oldStatus.includes("(Revisi ") ? "Laporan Revisi: " : "Laporan Penyelesaian: ") + completeData.message.trim();
            const parsed = parseEjoDescription(ejo.description);
            nextDescription = buildEjoDescription(parsed.descText, completionReason, completeData.attachments);
        }
    }

    const uRoleStr = state.currentUser ? (state.currentUser.role || '') : '';
    const roleSuffix = uRoleStr ? ` (${uRoleStr})` : '';
    const actorName = state.currentUser ? (state.currentUser.fullname || state.currentUser.username) : 'User';

    let logMessage = `Status dirubah dari ${oldStatus} menjadi ${finalStatus} oleh ${actorName}${roleSuffix}.${rejectionReason ? ' Alasan Penolakan: ' + rejectionReason : ''}`;
    if (finalStatus.startsWith('In Progress') && finalEngineer && finalEngineer !== 'Unassigned') {
        logMessage = `EJO ditugaskan kepada ${finalEngineer} (Status In Progress) oleh ${actorName}${roleSuffix}.`;
    } else if (oldStatus === 'Waiting Dept Approval' && finalStatus === 'Requested') {
        logMessage = `EJO disetujui oleh Manager/Supervisor ${state.currentUser.dept} (${actorName}).`;
    } else if (finalStatus === 'Checking') {
        logMessage = `EJO disetujui untuk pengecekan ${finalEngineer && finalEngineer !== 'Unassigned' ? 'oleh ' + finalEngineer : ''} (Foreman: ${actorName}).`;
    } else if (finalStatus === 'Pending User Approval') {
        logMessage = `Pekerjaan diselesaikan oleh ${finalEngineer && finalEngineer !== 'Unassigned' ? finalEngineer : actorName}, menunggu persetujuan User.`;
    } else if (finalStatus === 'Completed') {
        logMessage = `Pekerjaan selesai & disetujui oleh User (${actorName}).`;
    }
    if (rejectionImage) {
        logMessage += `<br/><img src="${rejectionImage}" onclick="openRejectionImage(this.src)" style="max-width: 100%; max-height: 150px; border-radius: var(--border-radius-sm); border: 1px solid var(--card-border); margin-top: 8px; cursor: pointer; display: block; object-fit: contain;" title="Klik untuk memperbesar gambar bukti penolakan" />`;
    }
    if (rejectionSignature) {
        logMessage += `<br/><div style="margin-top: 8px; display: inline-flex; flex-direction: column; align-items: flex-start; gap: 4px;"><span class="text-xs text-secondary" style="font-weight: 500;">Tanda Tangan Penolakan:</span><img src="${rejectionSignature}" style="max-width: 120px; max-height: 60px; background: #ffffff; border-radius: var(--border-radius-sm); border: 1px solid var(--card-border); display: block; object-fit: contain; padding: 2px;" /></div>`;
    }
    if (completionSignature) {
        logMessage += `<br/><div style="margin-top: 8px; display: inline-flex; flex-direction: column; align-items: flex-start; gap: 4px;"><span class="text-xs text-secondary" style="font-weight: 500;">Tanda Tangan Penyelesaian (${state.currentUser.role}):</span><img src="${completionSignature}" style="max-width: 120px; max-height: 60px; background: #ffffff; border-radius: var(--border-radius-sm); border: 1px solid var(--card-border); display: block; object-fit: contain; padding: 2px;" /></div>`;
    }

    if (finalStatus === 'Requested') {
        finalEstDate = "";
    }

    const currentLogs = parseLogs(ejo.logs || ejo);
    currentLogs.push({
        date: timestamp,
        message: logMessage
    });

    const updatedFields = {
        status: finalStatus,
        engineer: finalEngineer,
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0,
        approvals: approvalsObj,
        targetDate: finalTargetDate,
        estDate: finalEstDate,
        logs: JSON.stringify(currentLogs)
    };
    if (finalStatus.startsWith('In Progress') && !oldStatus.startsWith('In Progress')) {
        updatedFields.qty_needed_actual = 0;
        updatedFields.qty_stock = 0;
    }
    // ponytail: reset qty_work_confirmed when reverting from In Progress back to earlier status (NOT when moving to Done)
    // This ensures the "Konfirmasi Pekerjaan" button reappears when the EJO returns to In Progress
    const isDoneTransition = finalStatus === 'Pending User Approval' || finalStatus === 'Completed' || finalStatus === 'Done';
    if (oldStatus.startsWith('In Progress') && !finalStatus.startsWith('In Progress') && !isDoneTransition) {
        updatedFields.qty_work_confirmed = 0;
    }
    // ponytail: record done date when EJO transitions to Done/Completed/Pending User Approval
    if ((finalStatus === 'Pending User Approval' || finalStatus === 'Completed') && !oldStatus.startsWith('Pending User Approval') && oldStatus !== 'Completed') {
        updatedFields.qty_work_done_date = new Date().toISOString().slice(0, 10);
    }
    if (nextDescription !== undefined) {
        updatedFields.description = nextDescription;
    }

    try {
        const res = await fetch(`/api/general-ejos/${ejoId}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(updatedFields)
        });
        if (!res.ok) {
            const data = await res.json().catch(() => ({}));
            throw new Error(data.message || "Gagal mengubah status General EJO");
        }

        await initData();
        showToast(`General EJO ${ejoId} dipindahkan ke ${finalStatus}`, "success");
    } catch (err) {
        console.error(err);
        showToast(err.message || "Gagal memindahkan status di database server!", "error");
    }
}

// ponytail: Delete/cancel General EJO directly from Kanban card
async function deleteGeneralEjo(ejoId) {
    const ejo = getVisibleGeneralEjos().find(item => item.id === ejoId);
    if (!ejo) return;

    const isLead = state.currentUser && (isLeadRole(state.currentUser.role));
    const isRestrictedRole = state.currentUser && ['Foreman Eng', 'Supervisor Eng', 'Manager Eng', 'Plant Manager'].includes(state.currentUser.role);
    const isRequester = checkIsRequester(ejo.requester);
    const isSchedulePhase = ejo.status === 'Requested' || ejo.status === 'Approved' || (ejo.status || '').startsWith('Checking') || ejo.status === 'Waiting Dept Approval';

    let canDelete = (isLead && !isRestrictedRole) || (isRequester && isSchedulePhase);
    if (!canDelete) {
        showToast("Anda tidak memiliki wewenang untuk tindakan ini!", "error");
        return;
    }

    const confirmDel = await showCustomConfirm(`Apakah Anda yakin ingin membatalkan General Job Order ${ejoId}?`);
    if (!confirmDel) return;

    try {
        const queryParam = `?requester=${encodeURIComponent(state.currentUser.username)}`;
        const res = await fetch(`/api/general-ejos/${ejoId}${queryParam}`, {
            method: "DELETE"
        });
        if (!res.ok) throw new Error("Gagal menghapus General EJO");

        await initData();
        showToast(`General Job Order ${ejoId} berhasil dibatalkan`, "warning");
        renderGeneralEJO();
    } catch (err) {
        console.error(err);
        showToast("Gagal membatalkan General EJO di database server!", "error");
    }
}

// ponytail: parseLogs helper to safely parse logs string or array, with non-enumerable caching to prevent lag and background poll JSON mismatches
function parseLogs(ejoOrLogs) {
    let list = [];
    if (!ejoOrLogs) {
        list = [];
    } else if (Array.isArray(ejoOrLogs)) {
        list = ejoOrLogs;
    } else if (typeof ejoOrLogs === 'object') {
        if (ejoOrLogs._parsedLogs) return ejoOrLogs._parsedLogs;
        let logs = ejoOrLogs.logs || [];
        if (Array.isArray(logs)) {
            list = logs;
        } else if (typeof logs === 'string') {
            try {
                list = JSON.parse(logs);
            } catch (e) {
                console.error("Gagal parse logs:", e);
                list = [];
            }
        } else {
            list = [];
        }
        try {
            Object.defineProperty(ejoOrLogs, '_parsedLogs', {
                value: list,
                writable: true,
                configurable: true,
                enumerable: false
            });
        } catch (e) {
            ejoOrLogs._parsedLogs = list;
        }
    } else if (typeof ejoOrLogs === 'string') {
        try {
            list = JSON.parse(ejoOrLogs);
        } catch (e) {
            list = [];
        }
    }

    // ponytail: populate cleanMessage to avoid running regexes on huge base64 signature/image strings (non-enumerable)
    if (Array.isArray(list)) {
        list.forEach(log => {
            if (log && log.message && typeof log.message === 'string' && !log.hasOwnProperty('cleanMessage')) {
                const cleanMsg = log.message.split(/<br|<div|<img/i)[0].trim();
                try {
                    Object.defineProperty(log, 'cleanMessage', {
                        value: cleanMsg,
                        writable: true,
                        configurable: true,
                        enumerable: false
                    });
                } catch (e) {
                    log.cleanMessage = cleanMsg;
                }
            }
        });
    }
    return list;
}

// ponytail: Calculate next revision status based on logs
function getNextRevisionStatus(ejo) {
    let maxRev = 0;
    const logs = parseLogs(ejo);
    logs.forEach(log => {
        const msg = log.cleanMessage || (log && typeof log.message === 'string' ? log.message : '');
        const match = msg.match(/In Progress \(Revisi (\d+)\)/);
        if (match) {
            const num = parseInt(match[1]);
            if (num > maxRev) maxRev = num;
        }
    });
    return `In Progress (Revisi ${maxRev + 1})`;
}

// ponytail: Helper to calculate the current revision count from logs
function getCurrentRevisionCount(ejo) {
    let maxRev = 0;
    const logs = parseLogs(ejo);
    logs.forEach(log => {
        const message = log.cleanMessage || (log && typeof log.message === 'string' ? log.message : '');
        const match = message.match(/\(Revisi (\d+)\)/);
        if (match) {
            const num = parseInt(match[1]);
            if (num > maxRev) maxRev = num;
        }
    });
    return maxRev;
}

// ponytail: Get the most recent In Progress status from logs to preserve revision numbers when rejecting approval
function getPreviousInProgressStatus(ejo) {
    const logs = parseLogs(ejo);
    for (let i = logs.length - 1; i >= 0; i--) {
        const msg = logs[i].cleanMessage || (logs[i] && typeof logs[i].message === 'string' ? logs[i].message : "");
        const match = msg.match(/Status dirubah dari (In Progress \(Revisi \d+\)|In Progress) menjadi (Pending Approval|Pending User Approval)/);
        if (match) {
            return match[1];
        }
    }
    let maxRev = 0;
    logs.forEach(log => {
        const msg = log.cleanMessage || (log && typeof log.message === 'string' ? log.message : '');
        const match = msg.match(/In Progress \(Revisi (\d+)\)/);
        if (match) {
            const num = parseInt(match[1]);
            if (num > maxRev) maxRev = num;
        }
    });
    if (maxRev > 0) {
        return `In Progress (Revisi ${maxRev})`;
    }
    return "In Progress";
}

// ponytail: Request EJO revision (changes status to Pending Revision)
async function requestEJORevision(ejoId) {
    let isGeneral = false;
    let ejo = state.ejos.find(e => e.id === ejoId);
    if (!ejo) {
        ejo = getVisibleGeneralEjos().find(e => e.id === ejoId);
        if (ejo) isGeneral = true;
    }
    if (!ejo) return;

    const userRole = state.currentUser ? state.currentUser.role : '';
    const isTechStaff = isDrafterRole(userRole) || userRole === 'user_ENG' || userRole === 'Staff ENG' || userRole === 'User ENG' || (userRole || '').startsWith('Staff ENG');
    const isRequester = checkIsRequester(ejo.requester);
    const isForemanAdmin = state.currentUser && isForemanAdminRole(state.currentUser.role);
    const isLeadUser = state.currentUser && isLeadRole(state.currentUser.role);

    if (isTechStaff && !isRequester && !isForemanAdmin && !isLeadUser) {
        showToast("Hanya Pemohon (Requester) atau Lead/Admin yang dapat mengajukan revisi EJO!", "error");
        return;
    }

    // ponytail: block revision if General EJO has already been revised once
    if (isGeneral && getCurrentRevisionCount(ejo) >= 1) {
        showToast("Batas maksimal revisi untuk General EJO adalah 1x!", "error");
        return;
    }

    // ponytail: rename Lead Engineer -> Foreman
    const isLead = state.currentUser && (isLeadRole(state.currentUser.role));

    let nextStatus = 'Pending Revision';
    let logMessage = '';

    if (isLead) {
        // Leader directly starts the revision with detailed instructions
        const explanationResult = await showCustomPrompt(
            "Masukkan rincian apa saja yang harus direvisi & di bagian mana:",
            "",
            "Instruksi Revisi (Lead/Admin)",
            true
        );
        if (explanationResult === null) return; // User cancelled
        const explanation = explanationResult.text;
        const fileUrl = explanationResult.fileUrl;
        if (explanation.trim() === "") {
            showToast("Instruksi revisi wajib diisi!", "warning");
            return;
        }
        nextStatus = getNextRevisionStatus(ejo);
        let attachmentText = fileUrl ? ` [Attachment: ${fileUrl}]` : '';
        logMessage = `Revisi DIAJUKAN oleh Lead/Admin - ${state.currentUser ? state.currentUser.fullname : 'Admin'}. Status kembali menjadi ${nextStatus}. Instruksi revisi: ${explanation.trim()}${attachmentText}`;
    } else {
        const explanationResult = await showCustomPrompt(
            "Masukkan alasan pengajuan revisi pekerjaan ini (bagian mana yang bermasalah & mengapa):",
            "",
            "Pengajuan Revisi",
            true
        );
        if (explanationResult === null) return; // User cancelled
        const explanation = explanationResult.text;
        const fileUrl = explanationResult.fileUrl;
        if (explanation.trim() === "") {
            showToast("Alasan pengajuan revisi wajib diisi!", "warning");
            return;
        }
        let attachmentText = fileUrl ? ` [Attachment: ${fileUrl}]` : '';
        logMessage = `Pengajuan REVISI diajukan oleh ${state.currentUser ? state.currentUser.fullname : 'User'}. Alasan revisi: ${explanation.trim()}${attachmentText}`;
    }

    const now = new Date();
    const timestamp = now.getFullYear() + "-" +
        String(now.getMonth() + 1).padStart(2, '0') + "-" +
        String(now.getDate()).padStart(2, '0') + " " +
        String(now.getHours()).padStart(2, '0') + ":" +
        String(now.getMinutes()).padStart(2, '0');

    const updatedFields = {
        status: nextStatus,
        engineer: ejo.engineer || 'Unassigned',
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0,
        logs: [{
            date: timestamp,
            message: logMessage
        }]
    };

    try {
        const apiUrl = isGeneral ? `/api/general-ejos/${ejo.id}` : `/api/ejos/${ejo.id}`;
        const res = await fetch(apiUrl, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(updatedFields)
        });
        if (!res.ok) throw new Error("Gagal mengajukan revisi");

        await initData();
        closeModal();
        showToast(isLead ? `Revisi ${ejo.id} berhasil dimulai!` : "Pengajuan revisi berhasil diajukan!", "success");
    } catch (err) {
        console.error(err);
        showToast("Gagal menyimpan pengajuan revisi ke database server!", "error");
    }
}

// ponytail: Approve or Reject EJO revision
async function approveEJORevision(ejoId, isApproved) {
    let isGeneral = false;
    let ejo = state.ejos.find(e => e.id === ejoId);
    if (!ejo) {
        ejo = getVisibleGeneralEjos().find(e => e.id === ejoId);
        if (ejo) isGeneral = true;
    }
    if (!ejo) return;

    // ponytail: skip custom confirm modal for general EJO approval since we show the detailed assignment/upload modal
    if (!isGeneral || !isApproved) {
        const actionText = isApproved ? "menyetujui" : "menolak";
        const confirmApp = await showCustomConfirm(`Apakah Anda yakin ingin ${actionText} pengajuan revisi ini?`);
        if (!confirmApp) return;
    }

    let nextStatus = 'Completed';
    let logMessage = '';

    const now = new Date();
    const timestamp = now.getFullYear() + "-" +
        String(now.getMonth() + 1).padStart(2, '0') + "-" +
        String(now.getDate()).padStart(2, '0') + " " +
        String(now.getHours()).padStart(2, '0') + ":" +
        String(now.getMinutes()).padStart(2, '0');

    let finalEngineer = ejo.engineer || 'Unassigned';
    let finalTargetDate = ejo.targetDate;
    if (isApproved) {
        // ponytail: prevent approving if General EJO already reached max revision limit
        if (isGeneral && getCurrentRevisionCount(ejo) >= 1) {
            showToast("Batas maksimal revisi untuk General EJO adalah 1x!", "error");
            return;
        }
        if (isGeneral) {
            const approvalData = await showGeneralEjoApprovalModal(ejo);
            if (!approvalData) return; // User cancelled

            if (approvalData.engineers.length === 0) {
                showToast("Pekerjaan tidak dapat disetujui tanpa penugasan engineer!", "warning");
                return;
            }

            // ponytail: upload drawing if Drawing Ready is checked
            if (approvalData.drawingFile) {
                try {
                    await uploadDrawingFileDuringApproval(ejo, approvalData.drawingFile);
                } catch (err) {
                    return; // Stop revision approval if drawing upload fails
                }
            }

            finalEngineer = approvalData.engineers.join(', ');
            const nextRevCount = getCurrentRevisionCount(ejo) + 1;
            const revSuffix = ` (Revisi ${nextRevCount})`;

            nextStatus = `Checking (${approvalData.subStatus})` + revSuffix;
            finalTargetDate = approvalData.estDate;
        } else {
            nextStatus = getNextRevisionStatus(ejo);
        }
        logMessage = `Pengajuan revisi DISETUJUI oleh ${state.currentUser ? state.currentUser.fullname : 'Lead/Admin'}. Status kembali menjadi ${nextStatus}.`;
    } else {
        logMessage = `Pengajuan revisi DITOLAK oleh ${state.currentUser ? state.currentUser.fullname : 'Lead/Admin'}. Status kembali menjadi Completed.`;
    }

    const updatedFields = {
        status: nextStatus,
        engineer: finalEngineer,
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0,
        targetDate: finalTargetDate,
        logs: [{
            date: timestamp,
            message: logMessage
        }]
    };

    try {
        const apiUrl = isGeneral ? `/api/general-ejos/${ejo.id}` : `/api/ejos/${ejo.id}`;
        const res = await fetch(apiUrl, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(updatedFields)
        });
        if (!res.ok) throw new Error("Gagal memproses revisi");

        await initData();
        closeModal();
        showToast(`Pengajuan revisi berhasil ${isApproved ? 'disetujui' : 'ditolak'}!`, "success");
    } catch (err) {
        console.error(err);
        showToast("Gagal menyimpan perubahan revisi ke database server!", "error");
    }
}

// ponytail: Archive General EJO (moves it to history and removes from Kanban)
async function archiveGeneralEJO(ejoId) {
    const ejo = getVisibleGeneralEjos().find(item => item.id === ejoId) || (state.generalEjos || []).find(item => item.id === ejoId);
    if (!ejo) return;

    const userRole = state.currentUser ? state.currentUser.role : '';
    const isTechStaff = isDrafterRole(userRole) || userRole === 'user_ENG' || userRole === 'Staff ENG' || userRole === 'User ENG' || (userRole || '').startsWith('Staff ENG');
    const isRequester = checkIsRequester(ejo.requester);
    const isForemanAdmin = state.currentUser && isForemanAdminRole(state.currentUser.role);
    const isLeadUser = state.currentUser && isLeadRole(state.currentUser.role);

    if (isTechStaff && !isRequester && !isForemanAdmin && !isLeadUser) {
        showToast("Hanya Pemohon (Requester) atau Lead/Admin yang dapat mengonfirmasi & mengarsipkan EJO!", "error");
        return;
    }

    // ponytail: Repair Part category check
    const isRepairPartCategory = ejo.category === 'Repair Part' || (ejo.category && ejo.category.toLowerCase().includes('repair'));

    // ponytail: Repair Part category - only redirect to cost modal if biaya perbaikan is not yet filled
    if (isRepairPartCategory) {
        const hasRepairCost = (parseFloat(ejo.repair_cost_per_day) > 0 && parseInt(ejo.repair_duration) > 0);
        if (!hasRepairCost) {
            openRepairPartCostModal(ejoId, { autoArchive: true });
            return;
        }
        // If cost IS filled, proceed with normal archive flow below
    }

    const isCancelled = ejo.status && (ejo.status === 'Cancelled' || ejo.status.includes('Cancelled') || ejo.status.includes('Ditolak'));

    // ponytail: Quantity Validation check before archiving ONLY for Repair Part category (bypassed if Cancelled/Ditolak)
    if (isRepairPartCategory && !isCancelled) {
        const qVal = parseInt(ejo.quantity || 1);
        const qNeededTarget = (ejo.qty_needed_target !== undefined && ejo.qty_needed_target !== null && parseInt(ejo.qty_needed_target) > 0)
            ? parseInt(ejo.qty_needed_target)
            : ((ejo.qty_needed !== undefined && ejo.qty_needed !== null && parseInt(ejo.qty_needed) > 0) ? parseInt(ejo.qty_needed) : 1);
        const qStockTarget = (ejo.qty_stock_target !== undefined && ejo.qty_stock_target !== null && parseInt(ejo.qty_stock_target) > 0)
            ? parseInt(ejo.qty_stock_target)
            : Math.max(0, qVal - qNeededTarget);

        const qNeededActual = (ejo.qty_needed_actual !== undefined && ejo.qty_needed_actual !== null)
            ? parseInt(ejo.qty_needed_actual)
            : 0;
        const qStockActual = (ejo.qty_stock !== undefined && ejo.qty_stock !== null) ? parseInt(ejo.qty_stock) : 0;

        if ((qNeededTarget > 0 && qNeededActual < qNeededTarget) || (qStockTarget > 0 && qStockActual < qStockTarget)) {
            showToast("Quantity mesin & stok harus terpenuhi.", "error");
            return;
        }
    }

    const confirmArch = await showCustomConfirm(`Apakah Anda yakin ingin memindahkan General EJO ${ejoId} ke History EJO?`);
    if (!confirmArch) return;

    const now = new Date();
    const timestamp = now.getFullYear() + "-" +
        String(now.getMonth() + 1).padStart(2, '0') + "-" +
        String(now.getDate()).padStart(2, '0') + " " +
        String(now.getHours()).padStart(2, '0') + ":" +
        String(now.getMinutes()).padStart(2, '0');

    const logMessage = isCancelled
        ? `Pekerjaan dibatalkan/ditolak dan diarsipkan ke History oleh ${state.currentUser ? state.currentUser.fullname : 'Lead/Admin'}.`
        : `Pekerjaan selesai sepenuhnya dan diarsipkan ke History oleh ${state.currentUser ? state.currentUser.fullname : 'Lead/Admin'}.`;

    const updatedFields = {
        status: isCancelled ? ejo.status : 'Completed',
        engineer: ejo.engineer || 'Unassigned',
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0,
        is_archived: 1,
        logs: [{
            date: timestamp,
            message: logMessage
        }]
    };

    try {
        const username = state.currentUser ? (state.currentUser.username || state.currentUser.fullname || '') : '';
        const res = await fetch(`/api/general-ejos/${ejoId}?requester=${encodeURIComponent(username)}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(updatedFields)
        });
        if (!res.ok) {
            const resData = await res.json().catch(() => ({}));
            throw new Error(resData.message || "Gagal mengarsipkan General EJO");
        }

        await initData();
        if (document.getElementById("ejo-modal")?.classList.contains("active")) {
            closeModal();
        }
        showToast(`General EJO ${ejoId} dipindahkan ke History`, "success");
    } catch (err) {
        console.error(err);
        showToast(err.message || "Gagal mengarsipkan EJO ke database server!", "error");
    }
}

// ponytail: shared duration calc for Repair Part EJO — dipakai modal, tabel detail, chart, dan modal detail supaya sinkron
// Auto-calculate duration from qty_work_confirmed_date until the EJO enters Done; once Done/Archived the value is FROZEN
// (pakai qty_work_done_date > repair_duration tersimpan > tanggal log "menjadi Completed"), tidak terus menghitung sampai today.
// Same day = 1, next day = 2, etc. Fallback ke createdDate/created_at untuk EJO lama tanpa tanggal konfirmasi.
function getRepairPartDuration(ejo) {
    if (!ejo) return 0;
    const savedDuration = parseInt(ejo.repair_duration) || 0;
    // Fallback: EJO lama tanpa qty_work_confirmed_date pakai createdDate agar durasi tidak 0
    const confirmDateStr = ejo.qty_work_confirmed_date || ejo.createdDate || ejo.created_at || "";
    if (!confirmDateStr) return savedDuration;
    const confirmDate = new Date(confirmDateStr.slice(0, 10) + 'T00:00:00');
    if (isNaN(confirmDate.getTime())) return savedDuration;

    // ponytail: durasi dihitung dari konfirmasi s/d masuk Done — setelah Done/Archived hitungan HARUS berhenti (freeze), tidak boleh nambah tiap hari
    const status = ejo.status || '';
    const isDonePhase = status === 'Completed' || status === 'Cancelled' || ejo.is_archived === 1 || ejo.is_archived === '1';

    let endDate;
    if (isDonePhase) {
        const doneDateStr = ejo.qty_work_done_date || "";
        if (doneDateStr) {
            endDate = new Date(doneDateStr.slice(0, 10) + 'T00:00:00');
        } else if (savedDuration > 0) {
            // Tidak ada tanggal done: nilai yang disimpan Foreman adalah durasi beku saat biaya disimpan
            return savedDuration;
        } else {
            // Fallback: tanggal saat status berubah menjadi Completed dari logs, kalau tidak ada pakai tanggal log terakhir
            const logs = parseLogs(ejo);
            let freezeStr = "";
            for (let i = logs.length - 1; i >= 0; i--) {
                if ((logs[i].message || '').includes('menjadi Completed')) { freezeStr = logs[i].date || ''; break; }
            }
            if (!freezeStr && logs.length > 0) freezeStr = logs[logs.length - 1].date || '';
            endDate = freezeStr ? new Date(String(freezeStr).slice(0, 10) + 'T00:00:00') : null;
            if (!endDate || isNaN(endDate.getTime())) return Math.max(savedDuration, 1);
        }
    } else {
        // Masih dikerjakan (On Progress): hitung sampai hari ini
        endDate = new Date();
        endDate.setHours(0, 0, 0, 0);
    }
    if (!endDate || isNaN(endDate.getTime())) return savedDuration;
    const diffMs = endDate.getTime() - confirmDate.getTime();
    const diffDays = Math.floor(diffMs / 86400000) + 1; // +1 karena hari konfirmasi dihitung
    return Math.max(1, diffDays);
}

// ponytail: State & Handlers for Repair Part Cost Modal
function openRepairPartCostModal(ejoId, options = {}) {
    // ponytail: Only Foreman Eng / Admin Eng can open the cost modal
    if (!state.currentUser || !isForemanAdminRole(state.currentUser.role)) {
        showToast("Hanya Foreman Eng atau Admin Eng yang diperbolehkan mengisi Biaya Perbaikan!", "error");
        return;
    }

    const ejo = (state.generalEjos || []).find(e => e.id === ejoId);
    if (!ejo) {
        showToast("General EJO tidak ditemukan", "error");
        return;
    }

    // Rule: Close overlapping detail modal (#ejo-modal) if open
    const ejoModal = document.getElementById("ejo-modal");
    if (ejoModal && (ejoModal.classList.contains("active") || ejoModal.style.display !== "none")) {
        closeModal();
    }

    state.activeRepairPartEjoId = ejoId;
    state.activeRepairPartAutoArchive = !!options.autoArchive;

    const ejoIdEl = document.getElementById("repair-part-cost-ejo-id");
    if (ejoIdEl) ejoIdEl.textContent = `${ejo.id} - ${ejo.title}`;

    const priceInput = document.getElementById("repair-part-cost-price-new");
    const durationInput = document.getElementById("repair-part-cost-duration");
    const costPerDayInput = document.getElementById("repair-part-cost-per-day");
    const quantityInput = document.getElementById("repair-part-cost-quantity");
    const saveBtn = document.getElementById("repair-part-cost-save-btn");

    if (priceInput) {
        priceInput.readOnly = true;
    }
    if (quantityInput) {
        quantityInput.readOnly = true;
        quantityInput.style.backgroundColor = "var(--bg-muted, #f3f4f6)";
        quantityInput.style.cursor = "not-allowed";
        quantityInput.style.opacity = "0.85";
    }

    const gejoPriceEl = document.getElementById("gejo-form-price-new");
    const gejoPriceVal = parseFloat(gejoPriceEl?.value) || 0;
    const existingPrice = parseFloat(ejo.part_price_new) || 0;
    const finalPrice = gejoPriceVal > 0 ? gejoPriceVal : (existingPrice > 0 ? existingPrice : 0);

    if (priceInput) priceInput.value = finalPrice > 0 ? finalPrice : (ejo.part_price_new || "");
    if (gejoPriceEl && finalPrice > 0 && (!gejoPriceEl.value || parseFloat(gejoPriceEl.value) === 0)) {
        gejoPriceEl.value = finalPrice;
    }
    if (durationInput) {
        // ponytail: Auto-calculate duration via shared helper (sinkron dengan tabel detail & chart)
        const autoDuration = getRepairPartDuration(ejo);
        durationInput.value = autoDuration;
        durationInput.readOnly = true;
        durationInput.style.backgroundColor = "var(--bg-muted, #f3f4f6)";
        durationInput.style.cursor = "not-allowed";
        durationInput.style.opacity = "0.85";
    }
    if (costPerDayInput) costPerDayInput.value = parseFloat(ejo.repair_cost_per_day) || 0;

    const existingQuantity = (ejo.target_quantity !== undefined && ejo.target_quantity !== null && ejo.target_quantity !== "")
        ? parseInt(ejo.target_quantity)
        : ((ejo.quantity_needed !== undefined && ejo.quantity_needed !== null && ejo.quantity_needed !== "")
            ? parseInt(ejo.quantity_needed)
            : ((ejo.quantity !== undefined && ejo.quantity !== null && ejo.quantity !== "")
                ? parseInt(ejo.quantity)
                : 0));
    const gejoQuantityVal = parseInt((document.getElementById("gejo-form-target-qty") || document.getElementById("gejo-form-quantity"))?.value) || 0;
    const finalQuantity = existingQuantity > 0 ? existingQuantity : (gejoQuantityVal > 0 ? gejoQuantityVal : 1);
    if (quantityInput) {
        quantityInput.value = finalQuantity;
        quantityInput.readOnly = true;
        quantityInput.style.backgroundColor = "var(--bg-muted, #f3f4f6)";
        quantityInput.style.cursor = "not-allowed";
        quantityInput.style.opacity = "0.85";
    }

    if (saveBtn) {
        if (options.autoArchive) {
            saveBtn.innerHTML = `<i data-lucide="archive" style="width:16px;height:16px;display:inline;"></i> Simpan &amp; Arsipkan EJO`;
        } else {
            saveBtn.innerHTML = `<i data-lucide="save" style="width:16px;height:16px;display:inline;"></i> Simpan Data Biaya`;
        }
    }

    // Wire real-time input listeners & bi-directional price and quantity sync
    [priceInput, durationInput, costPerDayInput, quantityInput].forEach(inputEl => {
        if (inputEl && !inputEl.dataset.costListenerBound) {
            inputEl.addEventListener("input", () => {
                if (inputEl === priceInput) {
                    const gejoPriceEl = document.getElementById("gejo-form-price-new");
                    if (gejoPriceEl) {
                        gejoPriceEl.value = priceInput.value;
                    }
                }
                if (inputEl === quantityInput) {
                    const gejoQtyEl = document.getElementById("gejo-form-quantity");
                    if (gejoQtyEl) {
                        gejoQtyEl.value = quantityInput.value;
                        if (typeof calcGejoQtyStock === "function") {
                            calcGejoQtyStock();
                        }
                    }
                }
                calculateRepairPartCostLive();
            });
            inputEl.dataset.costListenerBound = "true";
        }
    });

    calculateRepairPartCostLive();
    updateRepairPartCostQtyBadge();

    const modal = document.getElementById("gejo-repair-part-cost-modal");
    if (modal) {
        modal.style.display = "flex";
        if (window.lucide) lucide.createIcons();
    }
}

function closeRepairPartCostModal() {
    const modal = document.getElementById("gejo-repair-part-cost-modal");
    if (modal) modal.style.display = "none";
    state.activeRepairPartEjoId = null;
    state.activeRepairPartAutoArchive = false;
}

// ponytail: update quantity ratio badge (e.g. 25/25) on upper right of repair-part-cost-price-new field
// Uses the same formula as the job card: totalInput = qty_needed_actual + qty_stock
function updateRepairPartCostQtyBadge() {
    const badgeEl = document.getElementById("repair-part-cost-qty-badge");
    if (!badgeEl) return;

    const ejoId = state.activeRepairPartEjoId;
    const ejo = (state.generalEjos || []).find(e => e.id === ejoId) || (state.ejos || []).find(e => e.id === ejoId);

    // --- Compute totalTarget using the same logic as job card ---
    const quantityInput = document.getElementById("repair-part-cost-quantity");
    let qVal = parseInt(quantityInput?.value);
    if (isNaN(qVal) || qVal < 0) {
        qVal = (ejo && ejo.quantity !== undefined && ejo.quantity !== null) ? parseInt(ejo.quantity) : 1;
    }
    if (isNaN(qVal) || qVal < 0) qVal = 1;

    let qNeededTarget = 1;
    let qStockTarget = 0;
    if (ejo) {
        qNeededTarget = (ejo.qty_needed_target !== undefined && ejo.qty_needed_target !== null && parseInt(ejo.qty_needed_target) > 0)
            ? parseInt(ejo.qty_needed_target)
            : ((ejo.qty_needed !== undefined && ejo.qty_needed !== null && parseInt(ejo.qty_needed) > 0) ? parseInt(ejo.qty_needed) : 1);
        qStockTarget = (ejo.qty_stock_target !== undefined && ejo.qty_stock_target !== null && parseInt(ejo.qty_stock_target) > 0)
            ? parseInt(ejo.qty_stock_target)
            : Math.max(0, qVal - qNeededTarget);
    }
    const totalTarget = Math.max(qVal, qNeededTarget + qStockTarget);

    // --- Compute totalInput (completed) using the same logic as job card ---
    let totalInput = 0;
    if (ejo) {
        const qNeededActual = (ejo.qty_needed_actual !== undefined && ejo.qty_needed_actual !== null)
            ? parseInt(ejo.qty_needed_actual) : 0;
        const qStockActual = (ejo.qty_stock !== undefined && ejo.qty_stock !== null)
            ? parseInt(ejo.qty_stock) : 0;
        totalInput = qNeededActual + qStockActual;

        // Fallback: if both actuals are 0 but EJO is completed/archived, show full
        if (totalInput === 0 && (ejo.status === "Completed" || ejo.status === "Archived" || ejo.is_archived === 1)) {
            totalInput = totalTarget;
        }
    }

    badgeEl.textContent = `${totalInput}/${totalTarget}`;
    if (totalInput >= totalTarget && totalTarget > 0) {
        badgeEl.style.background = "rgba(16, 185, 129, 0.15)";
        badgeEl.style.color = "#10b981";
        badgeEl.style.borderColor = "rgba(16, 185, 129, 0.3)";
    } else {
        badgeEl.style.background = "rgba(239, 68, 68, 0.15)";
        badgeEl.style.color = "#ef4444";
        badgeEl.style.borderColor = "rgba(239, 68, 68, 0.3)";
    }
}

function calculateRepairPartCostLive() {
    const costPriceEl = document.getElementById("repair-part-cost-price-new");
    const gejoPriceEl = document.getElementById("gejo-form-price-new");
    const quantityInput = document.getElementById("repair-part-cost-quantity");

    if (costPriceEl) {
        costPriceEl.readOnly = true;
    }
    if (quantityInput) {
        quantityInput.readOnly = true;
        quantityInput.style.backgroundColor = "var(--bg-muted, #f3f4f6)";
        quantityInput.style.cursor = "not-allowed";
        quantityInput.style.opacity = "0.85";
    }

    let priceNew = 0.0;
    if (gejoPriceEl && gejoPriceEl.value !== "") {
        priceNew = parseFloat(gejoPriceEl.value) || 0.0;
        if (costPriceEl) costPriceEl.value = gejoPriceEl.value;
    } else if (costPriceEl && costPriceEl.value !== "") {
        priceNew = parseFloat(costPriceEl.value) || 0.0;
        if (gejoPriceEl && priceNew > 0) gejoPriceEl.value = priceNew;
    }

    const duration = parseInt(document.getElementById("repair-part-cost-duration")?.value) || 0;
    const costPerDay = parseFloat(document.getElementById("repair-part-cost-per-day")?.value) || 0.0;
    const gejoTargetQtyEl = document.getElementById("gejo-form-target-qty") || document.getElementById("gejo-form-quantity");
    const quantityVal = parseInt(quantityInput?.value) || parseInt(gejoTargetQtyEl?.value) || 1;
    const activeQty = quantityVal > 0 ? quantityVal : 1;
    if (quantityInput && (!quantityInput.value || parseInt(quantityInput.value) !== activeQty)) {
        quantityInput.value = activeQty;
    }

    // Formula per AGENTS.md rules:
    // Total Biaya Perbaikan = repair_duration * repair_cost_per_day
    // Cost Saving (Hemat) = part_price_new - Total Biaya Perbaikan
    const totalCost = duration * costPerDay;
    const costSaving = priceNew - totalCost;

    const totalEl = document.getElementById("repair-part-cost-total-display");
    const savingEl = document.getElementById("repair-part-cost-saving-display");

    if (totalEl) totalEl.textContent = "Rp " + totalCost.toLocaleString('id-ID');
    if (savingEl) {
        savingEl.textContent = "Rp " + costSaving.toLocaleString('id-ID');
        if (costSaving > 0) {
            savingEl.style.color = "var(--color-green)";
        } else if (costSaving < 0) {
            savingEl.style.color = "var(--color-rose)";
        } else {
            savingEl.style.color = "var(--text-muted)";
        }
    }

    updateRepairPartCostQtyBadge();
}

async function saveRepairPartCostModal() {
    const ejoId = state.activeRepairPartEjoId;
    if (!ejoId) return;

    const ejo = (state.generalEjos || []).find(e => e.id === ejoId);
    if (!ejo) return;

    const priceNew = parseFloat(document.getElementById("repair-part-cost-price-new")?.value) || 0.0;
    const duration = parseInt(document.getElementById("repair-part-cost-duration")?.value) || 0;
    const costPerDay = parseFloat(document.getElementById("repair-part-cost-per-day")?.value) || 0.0;
    const quantityEl = document.getElementById("repair-part-cost-quantity");
    const quantity = quantityEl ? (parseInt(quantityEl.value) || 1) : (ejo && ejo.quantity !== undefined && ejo.quantity !== null && parseInt(ejo.quantity) > 0 ? parseInt(ejo.quantity) : (parseInt(document.getElementById("gejo-form-quantity")?.value) || 1));

    if (duration < 0 || costPerDay < 0 || priceNew < 0 || quantity < 0) {
        showToast("Nilai biaya/durasi/quantity tidak boleh negatif!", "warning");
        return;
    }

    const isRepairPartCategory = ejo.category === 'Repair Part' || (ejo.category && ejo.category.toLowerCase().includes('repair'));
    const isAutoArchive = !!state.activeRepairPartAutoArchive;
    const isCancelled = ejo.status && (ejo.status === 'Cancelled' || ejo.status.includes('Cancelled') || ejo.status.includes('Ditolak'));

    if (isAutoArchive && !isCancelled && isRepairPartCategory) {
        const qVal = parseInt(ejo.quantity || 1);
        const qNeededTarget = (ejo.qty_needed_target !== undefined && ejo.qty_needed_target !== null && parseInt(ejo.qty_needed_target) > 0)
            ? parseInt(ejo.qty_needed_target)
            : ((ejo.qty_needed !== undefined && ejo.qty_needed !== null && parseInt(ejo.qty_needed) > 0) ? parseInt(ejo.qty_needed) : 1);
        const qStockTarget = (ejo.qty_stock_target !== undefined && ejo.qty_stock_target !== null && parseInt(ejo.qty_stock_target) > 0)
            ? parseInt(ejo.qty_stock_target)
            : Math.max(0, qVal - qNeededTarget);

        const qNeededActual = (ejo.qty_needed_actual !== undefined && ejo.qty_needed_actual !== null)
            ? parseInt(ejo.qty_needed_actual)
            : 0;
        const qStockActual = (ejo.qty_stock !== undefined && ejo.qty_stock !== null) ? parseInt(ejo.qty_stock) : 0;

        if ((qNeededTarget > 0 && qNeededActual < qNeededTarget) || (qStockTarget > 0 && qStockActual < qStockTarget)) {
            showToast("Quantity mesin & stok harus terpenuhi.", "error");
            return;
        }
    }

    const now = new Date();
    const timestamp = now.getFullYear() + "-" +
        String(now.getMonth() + 1).padStart(2, '0') + "-" +
        String(now.getDate()).padStart(2, '0') + " " +
        String(now.getHours()).padStart(2, '0') + ":" +
        String(now.getMinutes()).padStart(2, '0');

    const totalCost = duration * costPerDay;
    const costSaving = priceNew - totalCost;

    const logMessage = isAutoArchive
        ? (isCancelled
            ? `Pekerjaan dibatalkan/ditolak, data biaya perbaikan diperbarui (Qty: ${quantity}, Total Biaya Perbaikan: Rp ${totalCost.toLocaleString('id-ID')}, Cost Saving: Rp ${costSaving.toLocaleString('id-ID')}), dan diarsipkan ke History oleh ${state.currentUser ? state.currentUser.fullname : 'Admin'}.`
            : `Pekerjaan selesai sepenuhnya, data biaya perbaikan diperbarui (Qty: ${quantity}, Total Biaya Perbaikan: Rp ${totalCost.toLocaleString('id-ID')}, Cost Saving: Rp ${costSaving.toLocaleString('id-ID')}), dan diarsipkan ke History oleh ${state.currentUser ? state.currentUser.fullname : 'Admin'}.`)
        : `Data biaya perbaikan diperbarui: Qty ${quantity}, Durasi ${duration} hari, Tarif Rp ${costPerDay.toLocaleString('id-ID')}/hari, Total Biaya Rp ${totalCost.toLocaleString('id-ID')}.`;

    const qtyNeeded = (ejo.qty_needed !== undefined && ejo.qty_needed !== null) ? parseInt(ejo.qty_needed) : 0;
    const qtyStock = Math.max(0, quantity - qtyNeeded);

    const updatedFields = {
        part_price_new: priceNew,
        repair_duration: duration,
        repair_cost_per_day: costPerDay,
        quantity: quantity,
        qty_needed: qtyNeeded,
        qty_stock: qtyStock,
        status: isAutoArchive ? (isCancelled ? ejo.status : 'Completed') : (ejo.status || 'Completed'),
        is_archived: isAutoArchive ? 1 : (ejo.is_archived || 0),
        engineer: ejo.engineer || 'Unassigned',
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0,
        logs: [{
            date: timestamp,
            message: logMessage
        }]
    };
    // ponytail: record done date when archiving/completing if not already set
    if (isAutoArchive && !isCancelled && !ejo.qty_work_done_date) {
        updatedFields.qty_work_done_date = new Date().toISOString().slice(0, 10);
    }

    try {
        const username = state.currentUser ? (state.currentUser.username || state.currentUser.fullname || '') : '';
        const res = await fetch(`/api/general-ejos/${ejoId}?requester=${encodeURIComponent(username)}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(updatedFields)
        });
        if (!res.ok) {
            const data = await res.json().catch(() => ({}));
            throw new Error(data.message || "Gagal menyimpan data biaya perbaikan");
        }

        ejo.part_price_new = priceNew;
        ejo.repair_duration = duration;
        ejo.repair_cost_per_day = costPerDay;
        ejo.quantity = quantity;
        ejo.qty_stock = qtyStock;

        closeRepairPartCostModal();
        await initData();

        if (isAutoArchive) {
            showToast(`General EJO ${ejoId} dipindahkan ke History EJO dengan data biaya terverifikasi!`, "success");
        } else {
            showToast(`Data biaya perbaikan EJO ${ejoId} berhasil disimpan!`, "success");
        }
    } catch (err) {
        console.error(err);
        showToast(err.message || "Gagal menyimpan data biaya perbaikan di database server!", "error");
    }
}


async function createNewProject() {
    if (state.currentUser && (isOrdinaryUser(state.currentUser.role) || (state.currentUser.role || '').includes('Staff'))) {
        showToast("Akses ditolak. Jabatan Staff tidak memiliki akses untuk membuat Project baru.", "warning");
        return;
    }
    const title = (document.getElementById("proj-title")?.value || "").trim();
    const no_io = (document.getElementById("proj-no-io")?.value || "").trim();
    const no_moc = (document.getElementById("proj-no-moc")?.value || "").trim();
    const dept = document.getElementById("proj-dept")?.value || "PRD";
    const budget = parseInt(document.getElementById("proj-budget")?.value) || 0;
    const targetDate = "";
    const pic = state.currentUser ? state.currentUser.fullname : "System User";
    const desc = (document.getElementById("proj-desc")?.value || "").trim();

    if (!title) {
        showToast("Judul / Nama Project wajib diisi!", "warning");
        document.getElementById("proj-title")?.focus();
        return;
    }
    if (!no_io) {
        showToast("No IO wajib diisi!", "warning");
        document.getElementById("proj-no-io")?.focus();
        return;
    }
    if (!no_moc) {
        showToast("No MOC wajib diisi!", "warning");
        document.getElementById("proj-no-moc")?.focus();
        return;
    }
    if (!desc) {
        showToast("Deskripsi issue & benefit wajib diisi!", "warning");
        document.getElementById("proj-desc")?.focus();
        return;
    }

    // ponytail: validate file attachment extension before submission
    const fileInput = document.getElementById("proj-attachment");
    if (fileInput && fileInput.files.length > 0) {
        const file = fileInput.files[0];
        const ext = file.name.split('.').pop().toLowerCase();
        const allowed = ['jpg', 'jpeg', 'png', 'webp', 'pdf'];
        if (!allowed.includes(ext)) {
            showToast("Format file tidak didukung! Hanya diperbolehkan file foto (JPG, PNG, WEBP) atau PDF.", "warning");
            return;
        }
    }

    // Generate project code sequential
    const lastIdNum = state.projects.reduce((max, item) => {
        const parts = item.id.split('-');
        const num = parseInt(parts[2]);
        return num > max ? num : max;
    }, 3); // Starts from 3 based on mock dataset length

    const nextIdNum = lastIdNum + 1;
    const nextId = `PRJ-2026-${String(nextIdNum).padStart(3, '0')}`;

    // ponytail: Extract selected drawing from Autodetect or Select Dropdown
    const searchInput = document.getElementById("proj-form-drawing-search");
    const drawingSelect = document.getElementById("proj-drawing-select");
    let drawingId = (drawingSelect ? drawingSelect.value : "") || (searchInput ? (searchInput.dataset.selectedDrawingId || "") : "");
    if (!drawingId && searchInput && searchInput.value) {
        const valTrim = searchInput.value.trim().toLowerCase();
        const found = (state.drawings || []).find(d => d.id.toLowerCase() === valTrim || valTrim.startsWith(d.id.toLowerCase()));
        if (found) drawingId = found.id;
    }

    const selectedDrawing = drawingId ? (state.drawings || []).find(d => d.id === drawingId) : null;
    const drawingFile = selectedDrawing ? (selectedDrawing.file_path || "") : "";

    const docs = drawingFile ? [drawingFile] : [];
    const newProject = {
        id: nextId,
        title,
        no_io,
        no_moc,
        dept,
        budget,
        targetDate,
        pic,
        desc,
        drawing_id: drawingId,
        drawing_file: drawingFile,
        docs: docs,
        phase: 1, // Default to Phase 1: Inisialisasi Ide
        approvals: {}
    };

    try {
        const res = await fetch("/api/projects", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(newProject)
        });
        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.message || "Server error");
        }

        const resData = await res.json();
        const actualId = resData.id || nextId;

        // ponytail: Check if user uploaded a supporting attachment and upload it
        const fileInput = document.getElementById("proj-attachment");
        if (fileInput && fileInput.files.length > 0) {
            const fd = new FormData();
            fd.append("project_id", actualId);
            fd.append("file", fileInput.files[0]);
            fd.append("doc_type", "boq");

            const resUpload = await fetch("/api/projects/upload-doc", {
                method: "POST",
                body: fd
            });
            if (!resUpload.ok) {
                console.warn("Gagal mengunggah file pendukung, tetapi project berhasil dibuat.");
            }
        }

        await initData();

        // Reset Form
        if (typeof resetProjectForm === "function") {
            resetProjectForm();
        } else {
            document.getElementById("project-form").reset();
        }
        document.getElementById("project-form-container").style.display = 'none';
        document.getElementById("btn-toggle-new-project").innerHTML = '<i data-lucide="plus-circle"></i> Project Baru';
        lucide.createIcons();

        showToast(`Gagasan Project ${actualId} berhasil diajukan`, "success");
    } catch (err) {
        console.error(err);
        showToast(`Gagal menyimpan project ke database server! (${err.message})`, "error");
    }
}

window.moveProjectPhase = async function moveProjectPhase(projId, direction) {
    if (window.event) window.event.stopPropagation();
    console.log("moveProjectPhase invoked:", projId, direction);
    const proj = state.projects ? state.projects.find(p => String(p.id).trim() === String(projId).trim()) : null;
    if (!proj) {
        console.warn("Project not found in state.projects for ID:", projId);
        showToast(`Data project ${projId} tidak ditemukan!`, "error");
        return;
    }

    // ponytail: Drawing review-only projects cannot be moved to phase 2
    if (proj.is_review_only || proj.is_review_only === 1 || proj.is_review_only === '1' || proj.is_review_only === true) {
        showToast("Drawing EJO di project ini bersifat Review Only dan tidak dapat dialihkan ke fase 2!", "warning");
        return;
    }

    const oldPhase = parseInt(proj.phase) || 1;
    const dir = parseInt(direction) || 1;
    const newPhase = oldPhase + dir;

    if (newPhase >= 1 && newPhase <= 5) {
        let approvals = { ...(proj.approvals || {}) };

        if (oldPhase === 2) {
            const userRole = state.currentUser ? state.currentUser.role : "";
            const isAuthorized = isForemanAdminRole(userRole) || isLeadRole(userRole) || /foreman/i.test(userRole) || /admin/i.test(userRole) || userRole === 'Server' || (state.currentUser && state.currentUser.username === 'foreman');
            if (!isAuthorized) {
                showToast("Hanya Foreman atau Admin yang berhak memindahkan fase project di Fase 2!", "error");
                return;
            }
        } else if (oldPhase === 3 || oldPhase === 4) {
            const userRole = state.currentUser ? state.currentUser.role : "";
            const isAuthorized = isForemanAdminRole(userRole) || isLeadRole(userRole) || /foreman/i.test(userRole) || /admin/i.test(userRole) || userRole === 'Foreman Eng' || userRole === 'Admin Eng' || userRole === 'Server';
            if (!isAuthorized) {
                showToast("Hanya Foreman atau Admin yang berhak memindahkan fase project!", "error");
                return;
            }
        }

        if (direction > 0) {
            // Moving forward: require all 4 signatures in approvals to move to Fase 2!
            if (oldPhase === 1) {
                const hasBoq = (proj.docs && Array.isArray(proj.docs) && proj.docs.length > 0) || Boolean(proj.drawing_file);
                if (!hasBoq) {
                    showToast("Gagal! Anda WAJIB mengunggah dokumen BOQ (Bill of Quantities) terlebih dahulu di Fase 1 sebelum melanjutkan ke Pengadaan.", "warning");
                    return;
                }
            } else if (oldPhase === 3) {
                // Moving to Commissioning (Fase 4): require Execution Photo upload via popup modal
                const uploaded = await showProjectExecDocModal(projId);
                if (!uploaded) return;
            } else if (oldPhase === 4) {
                // Moving to Selesai (Fase 5): require Berita Acara Serah Terima Pekerjaan document & all 6 sequential signatures
                const handoverDocs = proj.handover_docs || [];
                if (handoverDocs.length === 0) {
                    showToast("Gagal! Anda WAJIB mengunggah Dokumen Berita Acara Serah Terima Pekerjaan di Fase 4 sebelum menyelesaikan EJO.", "warning");
                    return;
                }
                const handoverSigs = proj.handover_approvals || {};
                const handoverRoles = ['staff_eng', 'spv_eng', 'manager_eng', 'manager_user', 'spv_user', 'staff_user'];
                const missingRole = handoverRoles.find(r => !handoverSigs[r] || !handoverSigs[r].signature);
                if (missingRole) {
                    showToast("Gagal! Seluruh 6 tanda tangan Berita Acara (Staff ENG, Foreman ENG, Manager ENG, Manager User, SPV User, Staff User) WAJIB lengkap secara berurutan!", "warning");
                    openProjectDetails(null, projId);
                    return;
                }
            }
        }

        // ponytail: reset commissioning handover docs & signatures when reverting back to Phase 3 or earlier
        let updatePayload = { phase: newPhase, approvals: approvals };
        if (dir < 0 && newPhase < 4) {
            updatePayload.handover_docs = [];
            updatePayload.handover_approvals = {};
        }

        try {
            const res = await fetch(`/api/projects/${encodeURIComponent(projId)}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(updatePayload)
            });
            if (!res.ok) throw new Error("Gagal mengubah fase");

            await initData();

            if (newPhase === 4) {
                showToast(`Project ${proj.id} dipindahkan ke Fase 4: Commissioning & Serah Terima`, "info");
            } else if (newPhase === 5) {
                showToast(`Project ${proj.id} berhasil diselesaikan & diarsipkan`, "success");
            } else {
                showToast(`Project ${proj.id} dipindahkan ke Fase ${newPhase}`, "info");
            }
        } catch (err) {
            console.error(err);
            showToast("Gagal memindahkan fase di database server!", "error");
        }
    }
}

// ponytail: Edit Project ID for Foreman Eng / Admin Eng
window.editProjectId = async function editProjectId(projId) {
    const userRole = state.currentUser ? state.currentUser.role : '';
    const isAuthorized = isForemanAdminRole(userRole) || isLeadRole(userRole) || ['Foreman Eng', 'Admin Eng', 'Server'].includes(userRole);
    if (!isAuthorized) {
        showToast("Hanya Foreman Eng atau Admin Eng yang diperbolehkan mengedit ID Project!", "error");
        return;
    }

    const proj = state.projects ? state.projects.find(p => p.id === projId) : null;
    if (!proj) {
        showToast("Project tidak ditemukan!", "error");
        return;
    }

    const newId = await showCustomPrompt(
        "Masukkan ID Project baru (contoh: PRJ-2026-004):",
        proj.id,
        "Edit ID Project"
    );

    if (newId === null) return; // User cancelled
    const trimmedId = newId.trim().replace(/[\r\n\t]+/g, ' ');

    if (!trimmedId) {
        showToast("ID Project tidak boleh kosong!", "error");
        return;
    }

    if (trimmedId === proj.id) {
        return; // Unchanged
    }

    const exists = (state.projects || []).some(p => p.id === trimmedId && p.id !== proj.id);
    if (exists) {
        showToast(`ID Project '${trimmedId}' sudah digunakan!`, "error");
        return;
    }

    try {
        const res = await fetch(`/api/projects/${encodeURIComponent(proj.id)}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ new_id: trimmedId, id: trimmedId })
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.message || "Gagal memperbarui ID Project!");
        }

        const oldId = proj.id;
        proj.id = trimmedId;

        if (state.currentDetailProjectId === oldId) {
            state.currentDetailProjectId = trimmedId;
            openProjectDetails(null, trimmedId);
        }

        renderProjects();
        if (typeof lucide !== 'undefined') lucide.createIcons();
        showToast(`ID Project berhasil diperbarui menjadi ${trimmedId}!`, "success");
    } catch (err) {
        console.error("Error editing project ID:", err);
        showToast(err.message || "Gagal memperbarui ID Project", "error");
    }
};

// ponytail: Edit No IO for project by Foreman Eng / Admin Eng
window.editProjectIo = async function editProjectIo(projId) {
    const userRole = state.currentUser ? state.currentUser.role : '';
    const isAuthorized = isForemanAdminRole(userRole) || isLeadRole(userRole) || ['Foreman Eng', 'Admin Eng', 'Server'].includes(userRole);
    if (!isAuthorized) {
        showToast("Hanya Foreman Eng atau Admin Eng yang diperbolehkan mengedit No IO!", "error");
        return;
    }

    const proj = state.projects ? state.projects.find(p => p.id === projId) : null;
    if (!proj) {
        showToast("Project tidak ditemukan!", "error");
        return;
    }

    const newIo = await showCustomPrompt(
        "Masukkan No IO Project (kosongkan jika tidak ada):",
        proj.no_io || "",
        "Edit No IO Project"
    );

    if (newIo === null) return; // User cancelled
    const trimmedIo = newIo.trim().replace(/[\r\n\t]+/g, ' ');

    try {
        const res = await fetch(`/api/projects/${encodeURIComponent(proj.id)}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ no_io: trimmedIo })
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.message || "Gagal memperbarui No IO!");
        }

        proj.no_io = trimmedIo;

        if (state.currentDetailProjectId === proj.id) {
            openProjectDetails(null, proj.id);
        }

        renderProjects();
        if (typeof lucide !== 'undefined') lucide.createIcons();
        showToast("No IO berhasil diperbarui!", "success");
    } catch (err) {
        console.error("Error editing project IO:", err);
        showToast(err.message || "Gagal memperbarui No IO", "error");
    }
};

