// ponytail: Edit manual status for project by Foreman Eng / Admin Eng
window.editProjectCustomStatus = async function editProjectCustomStatus(projId) {
    const userRole = state.currentUser ? state.currentUser.role : '';
    const isAuthorized = isForemanAdminRole(userRole) || isLeadRole(userRole) || ['Foreman Eng', 'Admin Eng', 'Server'].includes(userRole);
    if (!isAuthorized) {
        showToast("Hanya Foreman Eng atau Admin Eng yang diperbolehkan menginput status!", "error");
        return;
    }

    const proj = state.projects ? state.projects.find(p => p.id === projId) : null;
    if (!proj) {
        showToast("Project tidak ditemukan!", "error");
        return;
    }

    const statusInput = await showCustomPrompt(
        "Masukkan status / catatan untuk project ini (kosongkan jika ingin menghapus):",
        proj.custom_status || "",
        "Input Status Project"
    );

    if (statusInput === null || statusInput === undefined) return; // User cancelled
    const rawText = typeof statusInput === 'object' ? (statusInput.text || '') : statusInput;
    const trimmedStatus = String(rawText || '').trim();

    try {
        const res = await fetch(`/api/projects/${encodeURIComponent(proj.id)}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ custom_status: trimmedStatus })
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.message || "Gagal memperbarui status!");
        }

        proj.custom_status = trimmedStatus;
        const projInState = state.projects ? state.projects.find(p => p.id === proj.id) : null;
        if (projInState) {
            projInState.custom_status = trimmedStatus;
        }

        if (state.currentDetailProjectId === proj.id) {
            openProjectDetails(null, proj.id);
        }

        renderProjects();
        if (typeof lucide !== 'undefined') lucide.createIcons();
        showToast("Status project berhasil diperbarui!", "success");
    } catch (err) {
        console.error("Error updating project custom status:", err);
        showToast(err.message || "Gagal memperbarui status project", "error");
    }
};

// ponytail: Edit manual PR, PO, GR progress percentage for Phase 2 project
window.editProjectProcurement = async function editProjectProcurement(projId) {
    const userRole = state.currentUser ? state.currentUser.role : '';
    const isAuthorized = isForemanAdminRole(userRole) || isLeadRole(userRole) || ['Foreman Eng', 'Admin Eng', 'Server'].includes(userRole);
    if (!isAuthorized) {
        showToast("Hanya Foreman Eng atau Admin Eng yang diperbolehkan menginput status PR/PO/GR!", "error");
        return;
    }

    const proj = state.projects ? state.projects.find(p => p.id === projId) : null;
    if (!proj) {
        showToast("Project tidak ditemukan!", "error");
        return;
    }

    const modal = document.getElementById("custom-procurement-modal");
    const titleEl = document.getElementById("procurement-modal-title");
    const inputPr = document.getElementById("procurement-input-pr");
    const inputPo = document.getElementById("procurement-input-po");
    const inputGr = document.getElementById("procurement-input-gr");
    const btnOk = document.getElementById("procurement-btn-ok");
    const btnCancel = document.getElementById("procurement-btn-cancel");

    if (!modal || !inputPr || !inputPo || !inputGr || !btnOk || !btnCancel) {
        return;
    }

    if (titleEl) titleEl.textContent = `Input Status Procurement (${proj.id})`;
    inputPr.value = proj.pr_percent !== undefined && proj.pr_percent !== null ? proj.pr_percent : 0;
    inputPo.value = proj.po_percent !== undefined && proj.po_percent !== null ? proj.po_percent : 0;
    inputGr.value = proj.gr_percent !== undefined && proj.gr_percent !== null ? proj.gr_percent : 0;

    modal.style.display = 'flex';
    if (window.lucide) lucide.createIcons();

    // ponytail: Smart Automated Percentage Formula & Balancer
    // When 1 or 2 fields are typed, remaining component(s) are automatically balanced to 100%.
    // "apabila minus maka jadikan hasil itu adalah plus, jika plus tetap plus"
    let editOrder = [];
    let isAutoCalculating = false;

    function getCleanNumber(input) {
        if (!input || !input.value.trim()) return 0;
        let v = parseInt(input.value, 10);
        if (isNaN(v)) return 0;
        return Math.abs(v); // Hasil akhir ga boleh minus: jika minus jadikan plus
    }

    function updateVisualSummary() {
        const pr = getCleanNumber(inputPr);
        const po = getCleanNumber(inputPo);
        const gr = getCleanNumber(inputGr);
        const total = pr + po + gr;

        const totalBadge = document.getElementById("procurement-total-badge");
        if (totalBadge) {
            totalBadge.textContent = `${total}%`;
            if (total === 100) {
                totalBadge.style.color = "var(--color-green)";
            } else if (total > 100) {
                totalBadge.style.color = "#f59e0b";
            } else {
                totalBadge.style.color = "var(--color-cyan)";
            }
        }

        const barPr = document.getElementById("procurement-bar-pr");
        const barPo = document.getElementById("procurement-bar-po");
        const barGr = document.getElementById("procurement-bar-gr");

        if (barPr && barPo && barGr) {
            const visualTotal = Math.max(100, total);
            barPr.style.width = `${(pr / visualTotal) * 100}%`;
            barPo.style.width = `${(po / visualTotal) * 100}%`;
            barGr.style.width = `${(gr / visualTotal) * 100}%`;
        }
    }

    function handleAutoCalc(changedKey) {
        if (isAutoCalculating) return;
        isAutoCalculating = true;

        try {
            const inputs = { pr: inputPr, po: inputPo, gr: inputGr };
            const currentInput = inputs[changedKey];

            // Normalize typed value: prevent negative, make positive
            if (currentInput) {
                let currentVal = currentInput.value.trim() === '' ? 0 : parseInt(currentInput.value, 10);
                if (isNaN(currentVal)) currentVal = 0;
                if (currentVal < 0) {
                    currentVal = Math.abs(currentVal);
                    currentInput.value = currentVal;
                }
            }

            // Track recent edit order
            editOrder = editOrder.filter(k => k !== changedKey);
            editOrder.push(changedKey);

            const allKeys = ['pr', 'po', 'gr'];
            const uneditedKeys = allKeys.filter(k => !editOrder.includes(k));

            if (editOrder.length === 1) {
                // 1 komponen diinput -> 2 komponen sisanya dibagi rata dari sisa 100%
                const k1 = editOrder[0];
                const v1 = getCleanNumber(inputs[k1]);
                let remainder = 100 - v1;
                // Apabila minus maka jadikan hasil itu adalah plus, jika plus tetap plus
                if (remainder < 0) remainder = Math.abs(remainder);
                remainder = Math.min(100, remainder);

                const k2 = uneditedKeys[0] || (k1 === 'pr' ? 'po' : 'pr');
                const k3 = uneditedKeys[1] || (k1 === 'gr' ? 'po' : 'gr');

                const half1 = Math.round(remainder / 2);
                const half2 = Math.max(0, remainder - half1);

                inputs[k2].value = half1;
                inputs[k3].value = half2;
            } else {
                // 2 atau 3 komponen: Cari 1 komponen target penampung sisa (yang unedited atau paling lama tidak diedit)
                let targetKey = uneditedKeys[0];
                if (!targetKey) {
                    targetKey = editOrder[0]; // Paling lama diedit
                }

                const otherKeys = allKeys.filter(k => k !== targetKey);
                const sumOthers = otherKeys.reduce((acc, k) => acc + getCleanNumber(inputs[k]), 0);

                let remainder = 100 - sumOthers;
                // Apabila minus maka jadikan hasil itu adalah plus, jika plus tetap plus
                if (remainder < 0) remainder = Math.abs(remainder);
                remainder = Math.min(100, remainder);

                inputs[targetKey].value = remainder;
            }

            updateVisualSummary();
        } finally {
            isAutoCalculating = false;
        }
    }

    const onInputPr = () => handleAutoCalc('pr');
    const onInputPo = () => handleAutoCalc('po');
    const onInputGr = () => handleAutoCalc('gr');

    inputPr.addEventListener('input', onInputPr);
    inputPo.addEventListener('input', onInputPo);
    inputGr.addEventListener('input', onInputGr);

    updateVisualSummary();

    const cleanupListeners = () => {
        inputPr.removeEventListener('input', onInputPr);
        inputPo.removeEventListener('input', onInputPo);
        inputGr.removeEventListener('input', onInputGr);
    };

    return new Promise((resolve) => {
        btnOk.onclick = async (e) => {
            if (e) e.preventDefault();

            let prVal = getCleanNumber(inputPr);
            let poVal = getCleanNumber(inputPo);
            let grVal = getCleanNumber(inputGr);

            if (prVal > 100) prVal = 100;
            if (poVal > 100) poVal = 100;
            if (grVal > 100) grVal = 100;

            try {
                const res = await fetch(`/api/projects/${encodeURIComponent(proj.id)}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        pr_percent: prVal,
                        po_percent: poVal,
                        gr_percent: grVal
                    })
                });

                if (!res.ok) {
                    const errData = await res.json().catch(() => ({}));
                    throw new Error(errData.message || "Gagal memperbarui status procurement!");
                }

                proj.pr_percent = prVal;
                proj.po_percent = poVal;
                proj.gr_percent = grVal;
                const projInState = state.projects ? state.projects.find(p => p.id === proj.id) : null;
                if (projInState) {
                    projInState.pr_percent = prVal;
                    projInState.po_percent = poVal;
                    projInState.gr_percent = grVal;
                }

                showToast("Status PR, PO, GR berhasil diperbarui!", "success");
                renderProjects();
                if (typeof lucide !== 'undefined') lucide.createIcons();

                const detailModal = document.getElementById("project-modal");
                if (detailModal && detailModal.style.display !== "none" && state.currentDetailProjectId === proj.id) {
                    openProjectDetails(null, proj.id);
                }
            } catch (err) {
                console.error("Error updating procurement progress:", err);
                showToast(err.message || "Gagal memperbarui status procurement!", "error");
            } finally {
                cleanupListeners();
                modal.style.display = 'none';
                btnOk.onclick = null;
                btnCancel.onclick = null;
                resolve();
            }
        };

        btnCancel.onclick = (e) => {
            if (e) e.preventDefault();
            cleanupListeners();
            modal.style.display = 'none';
            btnOk.onclick = null;
            btnCancel.onclick = null;
            resolve();
        };
    });
};

// ponytail: Open PR Formula Info Modal
// Formula: Progress PR (%) = (Total PR + Total Ready Stock WS/WSP) ÷ Total All Material × 100%
window.openPrCalculatorModal = function openPrCalculatorModal(projId) {
    const proj = state.projects ? state.projects.find(p => p.id === projId) : null;
    const modal = document.getElementById("pr-calculator-modal");
    const titleEl = document.getElementById("pr-calc-modal-title");
    const btnCancel = document.getElementById("pr-calc-btn-cancel");

    if (!modal) return;

    if (titleEl && proj) {
        titleEl.textContent = `Rumus Progress PR (${proj.id})`;
    }

    modal.style.display = "flex";
    if (window.lucide) lucide.createIcons();

    if (btnCancel) {
        btnCancel.onclick = (e) => {
            if (e) e.preventDefault();
            modal.style.display = "none";
        };
    }
};

async function deleteProject(projId) {
    const confirmDel = await showCustomConfirm(`Apakah Anda yakin ingin membatalkan project ${projId}?`);
    if (!confirmDel) return;

    try {
        const res = await fetch(`/api/projects/${encodeURIComponent(projId)}`, {
            method: "DELETE"
        });
        if (!res.ok) throw new Error("Gagal menghapus project");

        await initData();
        showToast(`Project ${projId} berhasil dibatalkan`, "warning");
    } catch (err) {
        console.error(err);
        showToast("Gagal membatalkan project di database server!", "error");
    }
}

// ponytail: upload project doc photos from Kanban card directly
async function uploadProjectDocFromCard(projId, inputEl) {
    const userRole = state.currentUser ? state.currentUser.role : "";
    const isAuthorized = userRole === 'Foreman Eng' || userRole === 'Admin Eng' || userRole === 'Server';
    if (!isAuthorized) {
        showToast("Hanya Foreman atau Admin yang diperbolehkan mengunggah foto dokumentasi!", "error");
        inputEl.value = "";
        return;
    }
    const files = inputEl.files;
    if (!files || files.length === 0) return;

    const allowed = ['.jpg', '.jpeg', '.png', '.webp'];
    let uploadedCount = 0;

    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const ext = '.' + file.name.split('.').pop().toLowerCase();
        if (!allowed.includes(ext)) {
            showToast(`Format file "${file.name}" tidak didukung! Hanya gambar (JPG, JPEG, PNG, WEBP) yang diperbolehkan.`, "error");
            continue;
        }

        const fd = new FormData();
        fd.append("file", file);
        fd.append("project_id", projId);
        fd.append("doc_type", "execution");

        try {
            const res = await fetch("/api/projects/upload-doc", {
                method: "POST",
                body: fd
            });
            const data = await res.json();
            if (!res.ok || data.status === "error") {
                throw new Error(data.message || "Gagal mengunggah foto");
            }

            const proj = state.projects.find(p => p.id === projId);
            if (proj) {
                proj.execution_docs = data.execution_docs;
            }
            uploadedCount++;
        } catch (err) {
            console.error(err);
            showToast(`Gagal mengunggah foto "${file.name}": ` + err.message, "error");
        }
    }

    if (uploadedCount > 0) {
        showToast(`${uploadedCount} Foto dokumentasi berhasil diunggah!`, "success");
    }
    inputEl.value = "";
    renderProjects();
}

// ponytail: upload project BOQ documents from Phase 1 Kanban card
async function uploadProjectBoqFromCard(projId, inputEl) {
    const proj = state.projects ? state.projects.find(p => p.id === projId) : null;
    if (!proj) return;
    if (proj.phase !== 1) {
        showToast("Upload BOQ hanya dapat dilakukan pada Fase 1!", "warning");
        inputEl.value = "";
        return;
    }

    const files = inputEl.files;
    if (!files || files.length === 0) return;

    const allowed = ['.jpg', '.jpeg', '.png', '.webp', '.pdf', '.xlsx', '.xls', '.csv'];
    let uploadedCount = 0;

    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const ext = '.' + file.name.split('.').pop().toLowerCase();
        if (!allowed.includes(ext)) {
            showToast(`Format file "${file.name}" tidak didukung!`, "error");
            continue;
        }

        const fd = new FormData();
        fd.append("file", file);
        fd.append("project_id", projId);
        fd.append("doc_type", "boq");

        try {
            const res = await fetch("/api/projects/upload-doc", {
                method: "POST",
                body: fd
            });
            const data = await res.json();
            if (!res.ok || data.status === "error") {
                throw new Error(data.message || "Gagal mengunggah file BOQ");
            }

            if (proj) {
                proj.docs = data.docs;
            }
            uploadedCount++;
        } catch (err) {
            console.error(err);
            showToast(`Gagal mengunggah file ${file.name}: ${err.message}`, "error");
        }
    }

    inputEl.value = "";
    if (uploadedCount > 0) {
        showToast(`${uploadedCount} Dokumen BOQ berhasil diunggah`, "success");
        await initData();
        if (state.currentDetailProjectId === projId) {
            openProjectDetails(null, projId);
        }
    }
}

// ponytail: delete project BOQ document in Phase 1
window.deleteProjectBoqDoc = async function deleteProjectBoqDoc(arg1, arg2, arg3) {
    let evt = null;
    let projId = "";
    let encodedDocUrl = "";

    if (arg1 && typeof arg1 === 'object' && (arg1.stopPropagation || arg1.target)) {
        evt = arg1;
        projId = arg2;
        encodedDocUrl = arg3;
    } else {
        projId = arg1;
        encodedDocUrl = arg2;
    }

    if (evt && evt.stopPropagation) evt.stopPropagation();
    if (evt && evt.preventDefault) evt.preventDefault();
    if (window.event && window.event.stopPropagation) window.event.stopPropagation();

    const docUrl = decodeURIComponent(encodedDocUrl || "");
    const targetFilename = (docUrl || '').split('?')[0].split('/').pop().toLowerCase();

    if (!targetFilename) return;

    const confirmDelete = await showCustomConfirm(`Apakah Anda yakin ingin menghapus dokumen BOQ ini?`);
    if (!confirmDelete) {
        return;
    }

    const proj = state.projects ? state.projects.find(p => p.id === projId) : null;
    if (!proj) {
        showToast("Data project tidak ditemukan!", "error");
        return;
    }

    if (proj.phase !== 1) {
        showToast("Penghapusan BOQ hanya diperbolehkan di Fase 1!", "warning");
        return;
    }

    let updatedDocs = (proj.docs || []).filter(d => {
        const u = getDocUrl(d);
        return u && u.split('?')[0].split('/').pop().toLowerCase() !== targetFilename;
    });
    let updatedDrawingFile = proj.drawing_file || "";
    if (updatedDrawingFile && updatedDrawingFile.split('?')[0].split('/').pop().toLowerCase() === targetFilename) {
        updatedDrawingFile = "";
    }

    try {
        const res = await fetch(`/api/projects/${projId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                docs: updatedDocs,
                drawing_file: updatedDrawingFile
            })
        });

        if (!res.ok) throw new Error("Gagal menghapus BOQ di server");

        await initData();

        showToast("Dokumen BOQ berhasil dihapus!", "success");

        if (state.currentDetailProjectId === projId) {
            openProjectDetails(null, projId);
        }
    } catch (err) {
        console.error(err);
        showToast("Gagal menghapus dokumen BOQ!", "error");
    }
};

