// ponytail: Global capture-phase event listener fallback to GUARANTEE BOQ modal pops up whenever "Barang Ready" button is clicked
document.addEventListener("click", function (evt) {
    const btn = evt.target ? evt.target.closest("button") : null;
    if (!btn) return;

    // Ignore navigation buttons, sub-buttons, sidebar buttons, control bar buttons, and modal elements
    if (btn.classList.contains("nav-btn") || btn.classList.contains("sub-btn") || btn.hasAttribute("data-tab") || btn.hasAttribute("data-phase") || btn.closest(".sidebar, .sidebar-nav, .control-bar, .modal-backdrop, .modal-card, .results-meta")) {
        return;
    }

    const btnText = btn.textContent || btn.innerText || "";
    const onclickAttr = btn.getAttribute("onclick") || "";

    // Do NOT intercept back/revert buttons (e.g. "← Fase 3" or moveProjectPhase with -1)
    const isBackward = btnText.includes("←") || btnText.includes("<-") || onclickAttr.includes(", -1") || onclickAttr.includes(",-1");
    if (isBackward) return;

    // Must be inside a project card or have moveProjectPhase in onclick with forward direction
    const card = btn.closest(".project-card");
    const isCardMoveAction = card && (onclickAttr.includes("moveProjectPhase") || btnText.includes("Barang Ready") || (btnText.includes("Fase 3") && btnText.includes("→")));

    if (isCardMoveAction && (btnText.includes("Barang Ready") || (btnText.includes("Fase 3") && btnText.includes("→")))) {
        evt.preventDefault();
        evt.stopPropagation();
        if (evt.stopImmediatePropagation) evt.stopImmediatePropagation();

        // Extract project ID from onclick attribute or parent project card
        let projId = null;
        const match = onclickAttr.match(/moveProjectPhase\s*\(\s*['"]([^'"]+)['"]/);
        if (match) {
            projId = match[1];
        } else if (card) {
            projId = card.dataset.projectId || (card.querySelector(".project-card-id") ? (card.querySelector(".project-card-id").dataset.id || card.querySelector(".project-card-id").textContent.trim()) : null);
        }

        if (!projId && card) {
            // Fallback: search for any card with ID PRJ-
            if (card.innerText.includes("PRJ-")) {
                const matchId = card.innerText.match(/PRJ-\d{4}-\d{3,4}/);
                if (matchId) projId = matchId[0];
            }
        }

        if (projId) {
            console.log("Global capture listener triggered Barang Ready modal for projId:", projId);
            window.moveProjectPhase(projId, 1);
        } else {
            console.warn("Global capture listener: could not find projId from button click", btn);
        }
    }
}, true);

// ponytail: WSP Master Material parsing focused strictly on Material and Description with O(1) fast lookup index
function parseWSPMasterWorkbook(arrayBuffer) {
    if (typeof XLSX === "undefined") {
        console.warn("SheetJS XLSX library is not loaded.");
        return 0;
    }
    try {
        const data = new Uint8Array(arrayBuffer);
        const workbook = XLSX.read(data, { type: "array", dense: true });
        const sheetName = workbook.SheetNames.includes("NEW MASTER") ? "NEW MASTER" : workbook.SheetNames[0];
        const sheet = workbook.Sheets[sheetName];
        if (!sheet) return 0;

        const rawRows = XLSX.utils.sheet_to_json(sheet, { header: 1 });
        let headerIndex = -1;

        // Find header row (looks for 'Material' or 'Description')
        for (let i = 0; i < Math.min(15, rawRows.length); i++) {
            const rowStr = (rawRows[i] || []).join(" ").toLowerCase();
            if (rowStr.includes("material") || rowStr.includes("description")) {
                headerIndex = i;
                break;
            }
        }

        if (headerIndex === -1) headerIndex = 2; // fallback row index 2

        const headers = (rawRows[headerIndex] || []).map(h => String(h || "").trim());
        let matCol = headers.findIndex(h => /material/i.test(h));
        let descCol = headers.findIndex(h => /desc/i.test(h));
        let priceCol = headers.findIndex(h => /harga|price|sap/i.test(h));

        if (matCol === -1) matCol = 0;
        if (descCol === -1) descCol = 1;

        const materials = [];
        const wspMap = new Map();

        for (let i = headerIndex + 1; i < rawRows.length; i++) {
            const row = rawRows[i];
            if (!row || !row[matCol]) continue;
            const matCode = String(row[matCol]).trim();
            if (!matCode || matCode.toLowerCase() === "material") continue;
            const desc = row[descCol] ? String(row[descCol]).trim() : "";
            let price = 0;
            if (priceCol !== -1 && row[priceCol]) {
                const parsed = parseFloat(String(row[priceCol]).replace(/[^0-9.]/g, ""));
                if (!isNaN(parsed)) price = parsed;
            }

            const item = { material: matCode, description: desc, price: price };
            materials.push(item);

            // ponytail: O(1) index map by exact material code & combo key for instant search
            const codeKey = matCode.toLowerCase();
            wspMap.set(codeKey, item);
            wspMap.set(`${codeKey} - ${desc.toLowerCase()}`, item);
        }


        state.wspMaterials = materials;
        state.wspMap = wspMap;

        // Save to backend
        fetch("/api/wsp-materials/import", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(materials)
        }).then(r => r.json()).then(res => {
            console.log("WSP materials saved to database", res);
        }).catch(err => console.error("Error saving WSP", err));

        // ponytail: render lightweight top 50 datalist options using fast innerHTML string

        populateWSPMaterialDatalist();

        const infoEl = document.getElementById("gejo-wsp-status-info");
        if (infoEl) {
            infoEl.style.display = "block";
            infoEl.textContent = `✓ WSP Master Material dimuat (${materials.length.toLocaleString('id-ID')} items terdaftar)`;
        }
        return materials.length;
    } catch (err) {
        console.error("Error parsing WSP Master Material workbook:", err);
        return 0;
    }
}

// ponytail: Fast datalist population using innerHTML string with top 50 dynamic matches
// ponytail: populate semua datalist WSP yang ada di halaman (gejo-wsp-datalist + part-wsp-datalist)
function populateWSPMaterialDatalist(filterQuery = "") {
    if (!state.wspMaterials || !state.wspMaterials.length) return;

    let matches = state.wspMaterials;
    if (filterQuery && filterQuery.length >= 2) {
        const q = filterQuery.toLowerCase();
        matches = state.wspMaterials.filter(item =>
            item.material.toLowerCase().includes(q) || item.description.toLowerCase().includes(q)
        );
    }

    // ponytail: cap at top 50 items for instant DOM response without lagging browser input
    const slice = matches.slice(0, 50);
    const optionsHTML = slice.map(item =>
        `<option value="${item.material} - ${item.description}" data-mat="${item.material}" data-desc="${item.description}" data-price="${item.price}"></option>`
    ).join("");

    // ponytail: isi semua datalist WSP yang ada di DOM
    ["gejo-wsp-datalist", "part-wsp-datalist"].forEach(id => {
        const dl = document.getElementById(id);
        if (dl) dl.innerHTML = optionsHTML;
    });
}

function setupWSPMaterialEvents() {
    const uploadBtn = document.getElementById("gejo-wsp-upload-btn");
    const fileInput = document.getElementById("gejo-wsp-file-input");
    const searchInput = document.getElementById("gejo-form-wsp-search");

    if (uploadBtn && fileInput) {
        uploadBtn.addEventListener("click", () => fileInput.click());
        fileInput.addEventListener("change", (e) => {
            const file = e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (evt) => {
                const count = parseWSPMasterWorkbook(evt.target.result);
                if (count > 0 && typeof showToast === "function") {
                    showToast(`✓ Berhasil memuat WSP Master Material: ${count.toLocaleString('id-ID')} items!`, "success");
                }
            };
            reader.readAsArrayBuffer(file);
        });
    }

    const adminUploadBtn = document.getElementById("btn-wsp-admin-import");
    const adminFileInput = document.getElementById("wsp-admin-import-input");
    if (adminUploadBtn && adminFileInput) {
        adminUploadBtn.addEventListener("click", () => adminFileInput.click());
        adminFileInput.addEventListener("change", (e) => {
            const file = e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (evt) => {
                const count = parseWSPMasterWorkbook(evt.target.result);
                if (count > 0 && typeof showToast === "function") {
                    showToast(`✓ Berhasil mengimpor WSP Master Material (${count.toLocaleString('id-ID')} items)!`, "success");
                }
            };
            reader.readAsArrayBuffer(file);
        });
    }

    if (searchInput) {
        let debounceTimer = null;
        const handleSearchMatch = (e) => {
            const val = searchInput.value.trim();
            const infoEl = document.getElementById("gejo-wsp-status-info");

            if (!val) {
                if (infoEl) infoEl.style.display = "none";
                return;
            }
            if (!state.wspMaterials || !state.wspMaterials.length) return;

            // ponytail: dynamically update datalist options on input with light 100ms debounce
            if (e && e.type === "input") {
                clearTimeout(debounceTimer);
                debounceTimer = setTimeout(() => populateWSPMaterialDatalist(val), 100);
            }

            // ponytail: O(1) instant map lookup by key first, then fast array match fallback
            const valLower = val.toLowerCase();
            let matched = state.wspMap ? state.wspMap.get(valLower) : null;
            if (!matched && state.wspMaterials) {
                matched = state.wspMaterials.find(item =>
                    item.material.toLowerCase() === valLower ||
                    `${item.material} - ${item.description}`.toLowerCase() === valLower
                ) || state.wspMaterials.find(item =>
                    item.material.toLowerCase().includes(valLower) ||
                    item.description.toLowerCase().includes(valLower)
                );
            }

            if (matched) {
                // ponytail: auto-fill price only & dispatch input event to sync cost calculation modal
                const priceInput = document.getElementById("gejo-form-price-new");
                if (priceInput && matched.price > 0) {
                    priceInput.value = matched.price;
                    priceInput.dispatchEvent(new Event("input", { bubbles: true }));
                }

                // ponytail: update status info label (do not overwrite title or description)
                if (infoEl) {
                    infoEl.style.display = "block";
                    infoEl.textContent = `✓ Terdeteksi WSP: ${matched.material} | ${matched.description}`;
                }
            }
        };

        searchInput.addEventListener("input", handleSearchMatch);
        searchInput.addEventListener("change", handleSearchMatch);
    }

    // ponytail: WSP Autodetect untuk form Upload Drawing (auto-fill part-name & part-code)
    const partWspSearch = document.getElementById("part-wsp-search");
    if (partWspSearch) {
        let partWspDebounce = null;
        const partWspDatalist = document.getElementById("part-wsp-datalist");
        const partWspInfo = document.getElementById("part-wsp-status-info");

        partWspSearch.addEventListener("input", (e) => {
            const val = partWspSearch.value.trim();
            // ponytail: populate datalist dengan debounce (reuse populateWSPMaterialDatalist logic tapi untuk datalist berbeda)
            clearTimeout(partWspDebounce);
            partWspDebounce = setTimeout(() => {
                if (!state.wspMaterials || !state.wspMaterials.length) return;
                const q = val.toLowerCase();
                let matches = state.wspMaterials;
                if (q.length >= 2) {
                    matches = state.wspMaterials.filter(item =>
                        item.material.toLowerCase().includes(q) || item.description.toLowerCase().includes(q)
                    );
                }
                const slice = matches.slice(0, 50);
                if (partWspDatalist) {
                    partWspDatalist.innerHTML = slice.map(item =>
                        `<option value="${item.material} - ${item.description}" data-mat="${item.material}" data-desc="${item.description}" data-price="${item.price}"></option>`
                    ).join("");
                }
                if (partWspInfo && q.length >= 2) {
                    partWspInfo.style.display = "block";
                    partWspInfo.textContent = `${matches.length.toLocaleString('id-ID')} item ditemukan`;
                }
            }, 100);
        });

        partWspSearch.addEventListener("change", () => {
            const val = partWspSearch.value.trim();
            if (!val || !state.wspMaterials || !state.wspMaterials.length) return;
            const valLower = val.toLowerCase();
            // ponytail: cari match exact dulu (via wspMap), lalu fallback contains
            let matched = state.wspMap ? state.wspMap.get(valLower) : null;
            if (!matched) {
                matched = state.wspMaterials.find(item =>
                    item.material.toLowerCase() === valLower ||
                    `${item.material} - ${item.description}`.toLowerCase() === valLower
                ) || state.wspMaterials.find(item =>
                    item.material.toLowerCase().includes(valLower) ||
                    item.description.toLowerCase().includes(valLower)
                );
            }
            if (matched) {
                // ponytail: tampilkan info WSP yang cocok
                if (partWspInfo) {
                    partWspInfo.style.display = "block";
                    partWspInfo.style.color = "var(--color-green)";
                    partWspInfo.textContent = `✓ Ditemukan: ${matched.material} | ${matched.description}`;
                }
            }
        });
    }

    // Auto-fetch default local WSP Master Material file on startup if present
    fetch("/api/wsp-materials")
        .then(res => {
            if (!res.ok) return null;
            return res.json();
        })
        .then(data => {
            if (Array.isArray(data) && data.length > 0) {
                wspMasterData = data;
            }
        })
        .catch(() => {});
}

// ponytail: initialize WSP, Drawing Autodetect, & Form Inactivity Auto-Close when DOM ready
if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => {
        if (typeof loadWspFromDatabase === 'function') loadWspFromDatabase();
        if (typeof setupWSPMaterialEvents === 'function') setupWSPMaterialEvents();
        if (typeof window.setupProjectDrawingAutodetect === 'function') window.setupProjectDrawingAutodetect();
        if (typeof setupFormInactivityListeners === 'function') setupFormInactivityListeners();
    });
} else {
    if (typeof loadWspFromDatabase === 'function') loadWspFromDatabase();
    if (typeof setupWSPMaterialEvents === 'function') setupWSPMaterialEvents();
    if (typeof window.setupProjectDrawingAutodetect === 'function') window.setupProjectDrawingAutodetect();
    if (typeof setupFormInactivityListeners === 'function') setupFormInactivityListeners();
}

// ponytail: Modal & Submit handlers for transferring Drawing EJO to Project Monitoring (Fase 1 Review Only)
function openTransferDrawingToProjectModal(drawingId) {
    const userRole = state.currentUser ? state.currentUser.role : '';
    if (!isForemanAdminRole(userRole)) {
        showToast("Hanya Foreman dan Admin Eng yang dapat mengalihkan drawing ke Project!", "error");
        return;
    }
    const d = state.drawings ? state.drawings.find(item => item.id === drawingId) : null;
    if (!d) {
        showToast("Drawing EJO tidak ditemukan", "error");
        return;
    }
    const modal = document.getElementById("transfer-drawing-project-modal");
    if (!modal) return;
    document.getElementById("transfer-drawing-id").value = d.id;
    const infoId = document.getElementById("transfer-drawing-info-id");
    if (infoId) infoId.textContent = `${d.id} (${d.dept || 'ENG'})`;
    const infoTitle = document.getElementById("transfer-drawing-info-title");
    if (infoTitle) infoTitle.textContent = d.title || '-';
    const descEl = document.getElementById("transfer-project-desc");
    if (descEl) descEl.value = "";

    modal.style.display = "flex";
    if (window.lucide) lucide.createIcons();
}
window.openTransferDrawingToProjectModal = openTransferDrawingToProjectModal;

function closeTransferDrawingToProjectModal() {
    const modal = document.getElementById("transfer-drawing-project-modal");
    if (modal) modal.style.display = "none";
}
window.closeTransferDrawingToProjectModal = closeTransferDrawingToProjectModal;

function flexToProjectTab(drawingId) {
    const canReviewProject = canUserReviewProject(state.currentUser);

    if (!canReviewProject) {
        showToast("Project ini dikelola secara internal oleh Tim Engineering.", "info");
        return;
    }

    const projTabBtn = document.querySelector('[data-tab="projects"]');
    if (projTabBtn) {
        projTabBtn.click();
    } else {
        switchTab('projects');
    }

    const linkedProject = state.projects ? state.projects.find(p => p.drawing_id === drawingId || p.id === drawingId || p.ejo_id === drawingId) : null;
    if (linkedProject) {
        openProjectDetails(null, linkedProject.id);
        showToast(`Membuka Project (${linkedProject.id})`, "info");
    } else {
        showToast(`Membuka Project Review untuk Drawing ${drawingId}`, "info");
    }
}
window.flexToProjectTab = flexToProjectTab;

async function submitTransferDrawingToProject(e) {
    if (e) e.preventDefault();
    const userRole = state.currentUser ? state.currentUser.role : '';
    if (!isForemanAdminRole(userRole)) {
        showToast("Hanya Foreman dan Admin Eng yang dapat mengalihkan drawing ke Project!", "error");
        return;
    }
    const drawingId = document.getElementById("transfer-drawing-id")?.value;
    const d = state.drawings ? state.drawings.find(item => item.id === drawingId) : null;
    if (!d) {
        showToast("Drawing EJO tidak ditemukan", "error");
        return;
    }
    const manualDesc = document.getElementById("transfer-project-desc")?.value?.trim() || "";
    const finalDesc = manualDesc || `[Drawing Review] ${d.title}`;

    const btn = document.getElementById("btn-submit-transfer-drawing");
    if (btn) btn.disabled = true;

    try {
        const payload = {
            title: d.title,
            dept: d.dept || 'ENG',
            budget: 0,
            targetDate: d.targetDate || '',
            pic: d.uploader || (state.currentUser ? state.currentUser.fullname : 'System'),
            desc: finalDesc,
            phase: 1,
            is_review_only: 1,
            drawing_id: d.id,
            drawing_file: d.file_path || '',
            approvals: {},
            docs: d.file_path ? [d.file_path] : []
        };

        const res = await fetch("/api/projects", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });

        if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.message || "Gagal mengalihkan ke project");
        }

        const resData = await res.json();
        const newProjId = resData.id || (resData.data ? resData.data.id || resData.data.project_id : null);

        // update local state
        const newProj = {
            id: newProjId,
            title: payload.title,
            dept: payload.dept,
            budget: payload.budget,
            targetDate: payload.targetDate,
            pic: payload.pic,
            desc: payload.desc,
            phase: 1,
            is_review_only: 1,
            drawing_id: d.id,
            drawing_file: d.file_path || '',
            approvals: {},
            docs: payload.docs,
            createdDate: new Date().toISOString().substring(0, 10)
        };

        if (!state.projects) state.projects = [];
        state.projects.unshift(newProj);

        closeTransferDrawingToProjectModal();
        renderProjects();
        renderDrawings();
        showToast(`Drawing ${d.id} berhasil dialihkan ke Project (Fase 1 - Review Only)`, "success");
    } catch (err) {
        console.error("Error transferring drawing to project:", err);
        showToast(`Gagal: ${err.message}`, "error");
    } finally {
        if (btn) btn.disabled = false;
    }
}
window.submitTransferDrawingToProject = submitTransferDrawingToProject;

// ponytail: Project Timeline helper functions for Phase 3
window.closeProjectTimelineModal = function closeProjectTimelineModal() {
    const modal = document.getElementById("project-timeline-edit-modal");
    if (modal) modal.style.display = "none";
    state._currentTimelineProjId = null;
    state._editingTimeline = [];
};

window.updateProjectTimelineDesc = function updateProjectTimelineDesc(selectedIndex, projId, scope) {
    const proj = state.projects.find(p => p.id === projId);
    if (!proj) return;

    const timelineList = proj.timeline || [];
    let descText = "Belum ada data timeline untuk proyek ini.";

    if (selectedIndex !== "" && selectedIndex !== null && selectedIndex !== undefined) {
        const idx = parseInt(selectedIndex, 10);
        if (!isNaN(idx) && timelineList[idx]) {
            descText = timelineList[idx].desc || "Tidak ada deskripsi.";
        }
    }

    const descElemId = scope === 'modal' ? `project-timeline-desc-modal-${projId}` : `project-timeline-desc-card-${projId}`;
    const descElem = document.getElementById(descElemId);
    if (descElem) {
        descElem.textContent = descText;
    }
};

window.openEditProjectTimelineModal = function openEditProjectTimelineModal(projId) {
    const proj = state.projects.find(p => p.id === projId);
    if (!proj) return;

    state._currentTimelineProjId = proj.id;
    state._editingTimeline = JSON.parse(JSON.stringify(proj.timeline || []));

    const modalIdEl = document.getElementById("proj-timeline-modal-project-id");
    if (modalIdEl) modalIdEl.textContent = proj.id;

    renderEditingTimelineList();

    const dateInp = document.getElementById("input-new-timeline-date");
    const descInp = document.getElementById("input-new-timeline-desc");
    if (dateInp) dateInp.value = "";
    if (descInp) descInp.value = "";

    const modal = document.getElementById("project-timeline-edit-modal");
    if (modal) {
        modal.style.display = "flex";
        if (window.lucide) lucide.createIcons();
    }
};

function renderEditingTimelineList() {
    const container = document.getElementById("timeline-edit-items-container");
    if (!container) return;

    const items = state._editingTimeline || [];
    if (items.length === 0) {
        container.innerHTML = `<div style="padding: 12px; font-size: 0.78rem; color: var(--text-muted); text-align: center; font-style: italic;">Belum ada entri timeline. Gunakan form di bawah untuk menambah entri.</div>`;
        return;
    }

    container.innerHTML = items.map((item, idx) => {
        let dStr = item.date || "";
        return `
            <div style="display: grid; grid-template-columns: 1fr 2fr auto; gap: 8px; align-items: center; background: var(--bg-primary); padding: 6px 10px; border-radius: 4px; border: 1px solid var(--card-border);">
                <div>
                    <input type="date" class="input-sm" style="width: 100%; font-size: 0.8rem; box-sizing: border-box;" value="${dStr}" onchange="updateEditingTimelineField(${idx}, 'date', this.value)">
                </div>
                <div>
                    <input type="text" class="input-sm" style="width: 100%; font-size: 0.8rem; box-sizing: border-box;" value="${item.desc || ''}" placeholder="Deskripsi timeline..." onchange="updateEditingTimelineField(${idx}, 'desc', this.value)">
                </div>
                <div>
                    <button class="btn btn-outline btn-xs" onclick="removeEditingTimelineItem(${idx})" style="color: var(--color-red); border-color: rgba(239, 68, 68, 0.4); padding: 4px 6px;" title="Hapus Entri">
                        <i data-lucide="trash-2" style="width: 12px; height: 12px;"></i>
                    </button>
                </div>
            </div>
        `;
    }).join('');
    if (window.lucide) lucide.createIcons();
}
window.renderEditingTimelineList = renderEditingTimelineList;

window.updateEditingTimelineField = function updateEditingTimelineField(idx, field, value) {
    if (state._editingTimeline && state._editingTimeline[idx]) {
        state._editingTimeline[idx][field] = value;
    }
};

window.removeEditingTimelineItem = function removeEditingTimelineItem(idx) {
    if (state._editingTimeline && idx >= 0 && idx < state._editingTimeline.length) {
        state._editingTimeline.splice(idx, 1);
        renderEditingTimelineList();
    }
};

window.addTimelineItemToEditing = function addTimelineItemToEditing() {
    const dateInp = document.getElementById("input-new-timeline-date");
    const descInp = document.getElementById("input-new-timeline-desc");
    if (!dateInp || !descInp) return;

    const dateVal = dateInp.value.trim();
    const descVal = descInp.value.trim();

    if (!dateVal) {
        showToast("Mohon isi Tanggal, Bulan, Tahun terlebih dahulu!", "warning");
        return;
    }

    if (!state._editingTimeline) state._editingTimeline = [];
    state._editingTimeline.push({ date: dateVal, desc: descVal });

    dateInp.value = "";
    descInp.value = "";
    renderEditingTimelineList();
};

window.saveProjectTimeline = async function saveProjectTimeline() {
    const projId = state._currentTimelineProjId;
    if (!projId) return;

    const proj = state.projects.find(p => p.id === projId);
    if (!proj) return;

    const updatedTimeline = state._editingTimeline || [];

    // Sort timeline by date ascending
    updatedTimeline.sort((a, b) => (a.date || '').localeCompare(b.date || ''));

    try {
        const response = await fetch(`/api/projects/${encodeURIComponent(projId)}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ timeline: updatedTimeline })
        });

        if (!response.ok) {
            const errData = await response.json().catch(() => ({}));
            throw new Error(errData.message || "Gagal menyimpan timeline");
        }

        proj.timeline = updatedTimeline;

        window.closeProjectTimelineModal();
        showToast("Timeline proyek berhasil disimpan!", "success");

        renderProjects();

        // Refresh detail modal if currently open for this project
        const detailModal = document.getElementById("project-detail-modal");
        if (detailModal && detailModal.style.display !== "none" && state.currentDetailProjectId === projId) {
            openProjectDetails(null, projId);
        }
    } catch (err) {
        console.error("Save timeline error:", err);
        showToast(err.message || "Gagal menyimpan timeline proyek!", "error");
    }
};



// ponytail: Confirm work for EJO Repair Part — unlocks qty adjustment controls
window.confirmEjoQtyWork = async function (ejoId, event) {
    if (event) event.stopPropagation();

    // ponytail: Only assigned engineer + foreman can confirm work
    const uRole = state.currentUser ? (state.currentUser.role || '').toLowerCase() : '';
    const uName = state.currentUser ? (state.currentUser.username || '').toLowerCase() : '';
    const uFull = state.currentUser ? (state.currentUser.fullname || '').toLowerCase().trim() : '';
    const isForeman = uRole === 'foreman' || uRole === 'foreman_engineer' || uRole === 'foreman eng';

    // Find EJO first to check assigned engineer
    let ejoCheck = (state.generalEjos || []).find(item => item.id === ejoId || item.ejo_id === ejoId || String(item.id) === String(ejoId) || String(item.ejo_id) === String(ejoId));
    if (!ejoCheck && state.repairParts) {
        ejoCheck = (state.repairParts || []).find(item => item.id === ejoId || item.ejo_id === ejoId || String(item.id) === String(ejoId) || String(item.ejo_id) === String(ejoId));
    }
    const assignedEngineers = ejoCheck ? (ejoCheck.engineer || '').split(',').map(eng => eng.trim().toLowerCase()).filter(Boolean) : [];
    const isAssignedEngineer = assignedEngineers.includes(uFull) || assignedEngineers.includes(uName);

    const canConfirmWork = state.currentUser && (isAssignedEngineer || isForeman);

    if (!canConfirmWork) {
        showToast('Akses ditolak: Hanya Engineer yang ditunjuk dan Foreman yang dapat mengkonfirmasi pekerjaan.', 'error');
        return;
    }

    const ejo = ejoCheck;
    if (!ejo) {
        console.warn("confirmEjoQtyWork: EJO item not found for id:", ejoId);
        return;
    }

    const targetId = ejo.id || ejo.ejo_id || ejoId;

    // Confirmation dialog
    const confirmed = confirm(`Konfirmasi pekerjaan untuk EJO ${targetId}?\n\nSetelah dikonfirmasi, Anda dapat menginput quantity Mesin dan Stok pada repair part ini.`);
    if (!confirmed) return;

    const now = new Date();
    const timestamp = now.getFullYear() + "-" +
        String(now.getMonth() + 1).padStart(2, '0') + "-" +
        String(now.getDate()).padStart(2, '0') + " " +
        String(now.getHours()).padStart(2, '0') + ":" +
        String(now.getMinutes()).padStart(2, '0');

    const logs = parseLogs(ejo.logs || ejo);
    const userRoleStr = state.currentUser ? (state.currentUser.role || 'Repair Part') : 'Repair Part';
    const userFullNameStr = state.currentUser ? (state.currentUser.fullname || state.currentUser.username) : 'Engineer';
    logs.push({
        date: timestamp,
        message: `Pekerjaan Repair Part dikonfirmasi oleh ${userFullNameStr} (${userRoleStr}). Input alokasi quantity aktif.`
    });

    const payload = {
        qty_work_confirmed: 1,
        qty_work_confirmed_date: new Date().toISOString().slice(0, 10),
        status: ejo.status,
        engineer: ejo.engineer || 'Unassigned',
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0,
        logs: JSON.stringify(logs)
    };

    try {
        const res = await fetch(`/api/general-ejos/${encodeURIComponent(targetId)}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        if (!res.ok) {
            const errText = await res.text().catch(() => '');
            console.error(`confirmEjoQtyWork failed HTTP ${res.status}:`, errText);
            throw new Error(`Gagal mengkonfirmasi pekerjaan (HTTP ${res.status})`);
        }

        ejo.qty_work_confirmed = 1;
        ejo.qty_work_confirmed_date = payload.qty_work_confirmed_date;
        ejo.logs = logs;

        renderGeneralEJO();
        if (typeof renderPartlistTab === 'function') renderPartlistTab();
        if (typeof renderOverviewActivityLog === 'function') renderOverviewActivityLog();

        showToast(`✅ Pekerjaan EJO ${targetId} telah dikonfirmasi. Qty input aktif.`, "success");
    } catch (err) {
        console.error("confirmEjoQtyWork error:", err);
        showToast(err.message || "Gagal mengkonfirmasi pekerjaan!", "error");
    }
};

// ponytail: Reset allocation counts (Mesin & Stok actual) back to 0
window.resetEjoQtyAllocation = async function (ejoId, event) {
    if (event) event.stopPropagation();

    const uRole = state.currentUser ? (state.currentUser.role || '').toLowerCase() : '';
    const uName = state.currentUser ? (state.currentUser.username || '').toLowerCase() : '';
    const uFull = state.currentUser ? (state.currentUser.fullname || '').toLowerCase().trim() : '';

    let ejo = (state.generalEjos || []).find(item => item.id === ejoId || item.ejo_id === ejoId || String(item.id) === String(ejoId) || String(item.ejo_id) === String(ejoId));
    if (!ejo && state.repairParts) {
        ejo = (state.repairParts || []).find(item => item.id === ejoId || item.ejo_id === ejoId || String(item.id) === String(ejoId) || String(item.ejo_id) === String(ejoId));
    }
    if (!ejo) {
        console.warn("resetEjoQtyAllocation: EJO item not found for id:", ejoId);
        return;
    }

    // ponytail: Allow assigned engineer + standard canEditQty roles
    const assignedEngineers = (ejo.engineer || '').split(',').map(eng => eng.trim().toLowerCase()).filter(Boolean);
    const isAssignedEngineer = assignedEngineers.includes(uFull) || assignedEngineers.includes(uName);
    const canEditQty = state.currentUser && (
        isAssignedEngineer ||
        state.currentUser.role === 'admin' ||
        state.currentUser.role === 'foreman' ||
        state.currentUser.role === 'foreman_engineer' ||
        state.currentUser.username === 'admin' ||
        uRole === 'admin' ||
        uRole === 'foreman' ||
        uRole === 'foreman_engineer' ||
        uRole === 'foreman eng' ||
        uRole === 'admin eng' ||
        uRole === 'server' ||
        uName === 'admin' ||
        uName === 'server'
    );

    if (!canEditQty) {
        showToast('Akses ditolak: Hanya Engineer yang ditunjuk, Admin, dan Foreman yang dapat mengubah quantity.', 'error');
        return;
    }

    // ponytail: Guard — block if work not confirmed
    if (parseInt(ejo.qty_work_confirmed) !== 1) {
        showToast('Pekerjaan belum dikonfirmasi. Tekan "Konfirmasi Pekerjaan" terlebih dahulu.', 'warning');
        return;
    }

    const targetId = ejo.id || ejo.ejo_id || ejoId;
    const qVal = (parseInt(ejo.quantity) !== undefined && parseInt(ejo.quantity) !== null && parseInt(ejo.quantity) > 0) ? parseInt(ejo.quantity) : 1;
    let qtyNeededTarget = (ejo.qty_needed_target !== undefined && ejo.qty_needed_target !== null && parseInt(ejo.qty_needed_target) > 0)
        ? parseInt(ejo.qty_needed_target)
        : ((ejo.qty_needed !== undefined && ejo.qty_needed !== null && parseInt(ejo.qty_needed) > 0) ? parseInt(ejo.qty_needed) : 1);
    let qtyStockTarget = (ejo.qty_stock_target !== undefined && ejo.qty_stock_target !== null && parseInt(ejo.qty_stock_target) > 0)
        ? parseInt(ejo.qty_stock_target)
        : Math.max(0, qVal - qtyNeededTarget);
    const quantity = Math.max(qVal, qtyNeededTarget + qtyStockTarget);

    const usageType = ejo.usage_type || ejo.purpose || 'Kebutuhan Mesin';

    const payload = {
        quantity: quantity,
        qty_needed: 0,
        qty_needed_actual: 0,
        qty_needed_target: qtyNeededTarget,
        qty_stock: 0,
        qty_stock_target: qtyStockTarget,
        usage_type: usageType,
        purpose: usageType,
        status: ejo.status,
        engineer: ejo.engineer || 'Unassigned',
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0
    };

    try {
        const res = await fetch(`/api/general-ejos/${encodeURIComponent(targetId)}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        if (!res.ok) {
            const errText = await res.text().catch(() => '');
            console.error(`resetEjoQtyAllocation failed HTTP ${res.status}:`, errText);
            throw new Error(`Gagal mereset alokasi quantity (HTTP ${res.status})`);
        }

        ejo.quantity = quantity;
        ejo.qty_needed = 0;
        ejo.qty_needed_actual = 0;
        ejo.qty_needed_target = qtyNeededTarget;
        ejo.qty_stock = 0;
        ejo.qty_stock_target = qtyStockTarget;
        ejo.usage_type = usageType;
        ejo.purpose = usageType;

        renderGeneralEJO();
        if (typeof renderPartlistTab === 'function') renderPartlistTab();

        showToast(`Alokasi Qty EJO ${targetId} di-reset ke 0 Pcs`, "info");
    } catch (err) {
        console.error("resetEjoQtyAllocation error:", err);
        showToast(err.message || "Gagal mereset alokasi quantity!", "error");
    }
};

// ponytail: Targeted allocation adjuster (Mesin vs Stok) for EJO Repair Parts
window.adjustEjoQtyAllocation = async function (ejoId, targetType, delta, event) {
    if (event) event.stopPropagation();

    const uRole = state.currentUser ? (state.currentUser.role || '').toLowerCase() : '';
    const uName = state.currentUser ? (state.currentUser.username || '').toLowerCase() : '';
    const uFull = state.currentUser ? (state.currentUser.fullname || '').toLowerCase().trim() : '';

    let ejo = (state.generalEjos || []).find(item => item.id === ejoId || item.ejo_id === ejoId || String(item.id) === String(ejoId) || String(item.ejo_id) === String(ejoId));
    if (!ejo && state.repairParts) {
        ejo = (state.repairParts || []).find(item => item.id === ejoId || item.ejo_id === ejoId || String(item.id) === String(ejoId) || String(item.ejo_id) === String(ejoId));
    }
    if (!ejo) {
        console.warn("adjustEjoQtyAllocation: EJO item not found for id:", ejoId);
        return;
    }

    // ponytail: Allow assigned engineer + standard canEditQty roles
    const assignedEngineers = (ejo.engineer || '').split(',').map(eng => eng.trim().toLowerCase()).filter(Boolean);
    const isAssignedEngineer = assignedEngineers.includes(uFull) || assignedEngineers.includes(uName);
    const canEditQty = state.currentUser && (
        isAssignedEngineer ||
        state.currentUser.role === 'admin' ||
        state.currentUser.role === 'foreman' ||
        state.currentUser.role === 'foreman_engineer' ||
        state.currentUser.username === 'admin' ||
        uRole === 'admin' ||
        uRole === 'foreman' ||
        uRole === 'foreman_engineer' ||
        uRole === 'foreman eng' ||
        uRole === 'admin eng' ||
        uRole === 'server' ||
        uName === 'admin' ||
        uName === 'server'
    );

    if (!canEditQty) {
        showToast('Akses ditolak: Hanya Engineer yang ditunjuk, Admin, dan Foreman yang dapat mengubah quantity.', 'error');
        return;
    }

    // ponytail: Guard — block if work not confirmed
    if (parseInt(ejo.qty_work_confirmed) !== 1) {
        showToast('Pekerjaan belum dikonfirmasi. Tekan "Konfirmasi Pekerjaan" terlebih dahulu.', 'warning');
        return;
    }

    const targetId = ejo.id || ejo.ejo_id || ejoId;
    const qVal = (parseInt(ejo.quantity) !== undefined && parseInt(ejo.quantity) !== null && parseInt(ejo.quantity) > 0) ? parseInt(ejo.quantity) : 1;
    let qtyNeededTarget = (ejo.qty_needed_target !== undefined && ejo.qty_needed_target !== null && parseInt(ejo.qty_needed_target) > 0)
        ? parseInt(ejo.qty_needed_target)
        : ((ejo.qty_needed !== undefined && ejo.qty_needed !== null && parseInt(ejo.qty_needed) > 0) ? parseInt(ejo.qty_needed) : 1);
    let qtyStockTarget = (ejo.qty_stock_target !== undefined && ejo.qty_stock_target !== null && parseInt(ejo.qty_stock_target) > 0)
        ? parseInt(ejo.qty_stock_target)
        : Math.max(0, qVal - qtyNeededTarget);
    const quantity = Math.max(qVal, qtyNeededTarget + qtyStockTarget);

    let qtyNeeded = (ejo.qty_needed_actual !== undefined && ejo.qty_needed_actual !== null)
        ? parseInt(ejo.qty_needed_actual)
        : 0;
    let qtyStock = (ejo.qty_stock !== undefined && ejo.qty_stock !== null) ? parseInt(ejo.qty_stock) : 0;

    if (targetType === 'needed') {
        qtyNeeded = Math.max(0, Math.min(qtyNeededTarget, qtyNeeded + delta));
    } else if (targetType === 'stock') {
        qtyStock = Math.max(0, Math.min(qtyStockTarget, qtyStock + delta));
    } else {
        return;
    }

    const usageType = ejo.usage_type || ejo.purpose || 'Kebutuhan Mesin';

    const now = new Date();
    const timestamp = now.getFullYear() + "-" +
        String(now.getMonth() + 1).padStart(2, '0') + "-" +
        String(now.getDate()).padStart(2, '0') + " " +
        String(now.getHours()).padStart(2, '0') + ":" +
        String(now.getMinutes()).padStart(2, '0');

    const logs = parseLogs(ejo.logs || ejo);
    const userRoleStr = state.currentUser ? (state.currentUser.role || 'Repair Part') : 'Repair Part';
    const userFullNameStr = state.currentUser ? (state.currentUser.fullname || state.currentUser.username) : 'Engineer';
    logs.push({
        date: timestamp,
        message: `Update alokasi Qty (${targetType === 'needed' ? 'Mesin' : 'Stok'} ${delta > 0 ? '+' : ''}${delta}) oleh ${userFullNameStr} (${userRoleStr}). Alokasi saat ini: Mesin ${qtyNeeded}/${qtyNeededTarget} Pcs, Stok ${qtyStock}/${qtyStockTarget} Pcs.`
    });

    const payload = {
        quantity: quantity,
        qty_needed: qtyNeeded,
        qty_needed_actual: qtyNeeded,
        qty_needed_target: qtyNeededTarget,
        qty_stock: qtyStock,
        qty_stock_target: qtyStockTarget,
        usage_type: usageType,
        purpose: usageType,
        status: ejo.status,
        engineer: ejo.engineer || 'Unassigned',
        estCost: ejo.estCost || 0,
        actCost: ejo.actCost || 0,
        logs: JSON.stringify(logs)
    };

    try {
        const res = await fetch(`/api/general-ejos/${encodeURIComponent(targetId)}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        if (!res.ok) {
            const errText = await res.text().catch(() => '');
            console.error(`adjustEjoQtyAllocation failed HTTP ${res.status}:`, errText);
            throw new Error(`Gagal mengupdate alokasi quantity (HTTP ${res.status})`);
        }

        ejo.quantity = quantity;
        ejo.qty_needed = qtyNeeded;
        ejo.qty_needed_actual = qtyNeeded;
        ejo.qty_needed_target = qtyNeededTarget;
        ejo.qty_stock = qtyStock;
        ejo.qty_stock_target = qtyStockTarget;
        ejo.usage_type = usageType;
        ejo.purpose = usageType;
        ejo.logs = logs;

        renderGeneralEJO();
        if (typeof renderPartlistTab === 'function') renderPartlistTab();
        if (typeof renderOverviewActivityLog === 'function') renderOverviewActivityLog();

        showToast(`Alokasi Qty EJO ${targetId} diperbarui: Mesin ${qtyNeeded}/${qtyNeededTarget} Pcs, Stok ${qtyStock}/${qtyStockTarget} Pcs`, "success");
    } catch (err) {
        console.error("adjustEjoQtyAllocation error:", err);
        showToast(err.message || "Gagal memperbarui alokasi quantity!", "error");
    }
};

// ponytail: Quick Quantity Adjust for EJO Repair Parts in Sesi 2 / On Progress (Legacy handler redirect)
window.adjustEjoRepairPartQty = async function (ejoId, delta, event) {
    return window.adjustEjoQtyAllocation(ejoId, 'needed', delta, event);
};




async function loadWspFromDatabase() {
    try {
        const res = await fetch("/api/wsp-materials");
        if (res.ok) {
            const materials = await res.json();
            if (materials && Array.isArray(materials) && materials.length > 0) {
                state.wspMaterials = materials;
                const wspMap = new Map();
                materials.forEach(item => {
                    if (!item || !item.material) return;
                    const codeKey = item.material.toLowerCase();
                    wspMap.set(codeKey, item);
                    if (item.description) {
                        wspMap.set(`${codeKey} - ${item.description.toLowerCase()}`, item);
                    }
                });
                state.wspMap = wspMap;
                populateWSPMaterialDatalist();
                const infoEl = document.getElementById("gejo-wsp-status-info");
                if (infoEl) {
                    infoEl.style.display = "block";
                    infoEl.textContent = `✓ WSP Master Material dimuat (${materials.length.toLocaleString('id-ID')} items terdaftar)`;
                }
                console.log(`Loaded ${materials.length} WSP materials from database.`);
            }
        }
    } catch (e) {
        console.error("Failed to load WSP materials", e);
    }
}
